    p_starts_on + ((pw.week_number-1)*7 + (pw.day_number-1)),
    'assigned',
    (select auth.uid()),
    pw.notes
  from public.fitness_program_workouts pw
  where pw.program_id=p_program_id
  order by pw.week_number,pw.day_number;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'fitness_program_assigned','Fitness program assigned',v_title,(select auth.uid()),
    jsonb_build_object('fitness_plan_id',v_plan_id,'program_id',p_program_id,'starts_on',p_starts_on)
  );

  return v_plan_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_workout_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_membership uuid;
begin
  update public.client_workout_assignments
  set status='completed',updated_at=now()
  where id=NEW.assignment_id;

  select fp.membership_id into v_membership
  from public.client_workout_assignments wa
  join public.client_fitness_plans fp on fp.id=wa.fitness_plan_id
  where wa.id=NEW.assignment_id;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
  )
  values(
    NEW.contact_id,v_membership,'workouts',1,NEW.completed_at,NEW.source,NEW.created_by,
    jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
  );

  if NEW.duration_minutes is not null then
    insert into public.progress_entries(
      contact_id,membership_id,metric_key,value_numeric,recorded_at,source,created_by,metadata
    )
    values(
      NEW.contact_id,v_membership,'exercise_minutes',NEW.duration_minutes,NEW.completed_at,NEW.source,NEW.created_by,
      jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
    );
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    NEW.contact_id,'workout_completed','Workout completed',
    case when NEW.duration_minutes is not null then NEW.duration_minutes::text || ' minutes' else null end,
    NEW.created_by,
    jsonb_build_object('workout_completion_id',NEW.id,'assignment_id',NEW.assignment_id)
  );

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.update_direct_membership_access_readiness()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_journey_key text;
  v_payment_done boolean;
  v_vitality_done boolean;
begin
  if NEW.event_type not in ('payment_completed','vitality_completed','step_completed') then
    return NEW;
  end if;

  select journey_key into v_journey_key
  from public.contact_journeys
  where id=NEW.journey_id;

  if v_journey_key <> 'direct_membership' then
    return NEW;
  end if;

  select exists(
    select 1 from public.contact_journey_steps
    where journey_id=NEW.journey_id
      and step_key='payment_agreement'
      and status in ('completed','skipped','waived')
  ) into v_payment_done;

  select exists(
    select 1 from public.contact_journey_steps
    where journey_id=NEW.journey_id
      and step_key='vitality_assessment'
      and status in ('completed','skipped','waived')
  ) into v_vitality_done;

  if v_payment_done and v_vitality_done then
    update public.journey_enrollment_activations
    set access_status='active',
        updated_at=now()
    where journey_id=NEW.journey_id
      and access_status <> 'active';
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.repair_coach_conversation_participants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_conversation_id uuid;
  v_member_user uuid;
  v_old_coach uuid;
begin
  if NEW.assigned_coach_id is null then
    return NEW;
  end if;

  select user_id into v_member_user
  from public.client_access
  where contact_id=NEW.primary_contact_id
    and status='active'
  limit 1;

  v_conversation_id := private.ensure_coach_client_conversation(
    NEW.primary_contact_id,NEW.id,v_member_user,NEW.assigned_coach_id
  );

  if v_conversation_id is null then
    return NEW;
  end if;

  if TG_OP='UPDATE' and OLD.assigned_coach_id is distinct from NEW.assigned_coach_id and OLD.assigned_coach_id is not null then
    v_old_coach := OLD.assigned_coach_id;

    update public.member_conversation_participants
    set left_at=now()
    where conversation_id=v_conversation_id
      and user_id=v_old_coach
      and left_at is null;
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_coach_client_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_coach_id uuid;
  v_membership_id uuid;
begin
  if TG_TABLE_NAME='client_access' then
    if NEW.status <> 'active' or NEW.user_id is null then return NEW; end if;
    v_user_id := NEW.user_id;
    v_membership_id := NEW.membership_id;
    select assigned_coach_id into v_coach_id
    from public.client_memberships where id=NEW.membership_id;
    perform private.ensure_coach_client_conversation(
      NEW.contact_id,v_membership_id,v_user_id,v_coach_id
    );
    return NEW;
  end if;

  if TG_TABLE_NAME='client_memberships' then
    if NEW.assigned_coach_id is null then return NEW; end if;
    select user_id into v_user_id
    from public.client_access
    where contact_id=NEW.primary_contact_id and status='active';
    perform private.ensure_coach_client_conversation(
      NEW.primary_contact_id,NEW.id,v_user_id,NEW.assigned_coach_id
    );
    return NEW;
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_coach_client_conversation(p_contact_id uuid, p_membership_id uuid, p_member_user_id uuid, p_coach_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_conversation_id uuid;
  v_staff_role text;
begin
  if p_contact_id is null or p_member_user_id is null or p_coach_user_id is null then
    return null;
  end if;

  select id into v_conversation_id
  from public.member_conversations
  where contact_id=p_contact_id
    and conversation_type='coach_client'
    and status='active'
  order by created_at desc
  limit 1;

  if v_conversation_id is null then
    insert into public.member_conversations(
      conversation_type,contact_id,membership_id,title,status,created_by
    )
    values(
      'coach_client',p_contact_id,p_membership_id,'Your ReVitalized Coaching Conversation',
      'active',p_coach_user_id
    )
    returning id into v_conversation_id;
  else
    update public.member_conversations
    set membership_id=coalesce(p_membership_id,membership_id),updated_at=now()
    where id=v_conversation_id;
  end if;

  insert into public.member_conversation_participants(
    conversation_id,user_id,participant_type,contact_id
  )
  values(
    v_conversation_id,p_member_user_id,'member',p_contact_id
  )
  on conflict (conversation_id,user_id) do update
  set left_at=null,participant_type='member',contact_id=p_contact_id;

  select role into v_staff_role
  from public.staff_access
  where user_id=p_coach_user_id;

  insert into public.member_conversation_participants(
    conversation_id,user_id,participant_type,contact_id
  )
  values(
    v_conversation_id,p_coach_user_id,
    case
      when v_staff_role='owner' then 'owner'
      when v_staff_role='admin' then 'admin'
      when v_staff_role='support' then 'support'
      else 'coach'
    end,
    null
  )
  on conflict (conversation_id,user_id) do update
  set left_at=null,
      participant_type=excluded.participant_type;

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_program_course_to_existing_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_membership_id uuid;
begin
  v_program_code := coalesce(NEW.program_code, OLD.program_code);

  for v_membership_id in
    select cm.id
    from public.client_memberships cm
    where cm.program_code = v_program_code
  loop
    perform private.reconcile_membership_course_access(v_membership_id);
  end loop;

  if TG_OP = 'UPDATE' and OLD.program_code is distinct from NEW.program_code then
    for v_membership_id in
      select cm.id
      from public.client_memberships cm
      where cm.program_code = OLD.program_code
    loop
      perform private.reconcile_membership_course_access(v_membership_id);
    end loop;
  end if;

  return coalesce(NEW, OLD);
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_household_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_household_id uuid;
  v_membership_id uuid;
begin
  if TG_TABLE_NAME='client_access' then
    if NEW.status='active' and NEW.user_id is not null and NEW.household_id is not null then
      perform private.ensure_household_conversation(
        NEW.household_id,NEW.membership_id,NEW.user_id
      );
    end if;
    return NEW;
  end if;

  if TG_TABLE_NAME='household_members' then
    v_household_id := coalesce(NEW.household_id,OLD.household_id);

    select ca.membership_id into v_membership_id
    from public.client_access ca
    where ca.household_id=v_household_id
      and ca.membership_id is not null
    order by ca.created_at
    limit 1;

    perform private.ensure_household_conversation(
      v_household_id,v_membership_id,(select auth.uid())
    );
    return coalesce(NEW,OLD);
  end if;

  return coalesce(NEW,OLD);
end;
$function$

CREATE OR REPLACE FUNCTION private.recalculate_challenge_enrollment(p_enrollment_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_enrollment public.challenge_enrollments%rowtype;
  v_challenge public.wellness_challenges%rowtype;
  v_value numeric := 0;
  v_percent integer := 0;
  v_points integer := 0;
  v_was_completed boolean := false;
begin
  select * into v_enrollment
  from public.challenge_enrollments
  where id=p_enrollment_id;

  if v_enrollment.id is null then return; end if;

  select * into v_challenge
  from public.wellness_challenges
  where id=v_enrollment.challenge_id;

  if v_challenge.id is null or v_challenge.goal_type<>'metric' then return; end if;

  v_was_completed := v_enrollment.status='completed';

  if v_challenge.aggregation='sum' then
    select coalesce(sum(pe.value_numeric),0) into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.value_numeric is not null
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  elsif v_challenge.aggregation='count' then
    select count(*)::numeric into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  elsif v_challenge.aggregation='average' then
    select coalesce(avg(pe.value_numeric),0) into v_value
    from public.progress_entries pe
    where pe.metric_key=v_challenge.target_key
      and pe.value_numeric is not null
      and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
      and (
        (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
        or
        (v_enrollment.scope='household' and pe.contact_id in (
          select hm.contact_id from public.household_members hm
          where hm.household_id=v_enrollment.household_id and hm.status='active'
        ))
      );
  else
    select coalesce((
      select pe.value_numeric
      from public.progress_entries pe
      where pe.metric_key=v_challenge.target_key
        and pe.value_numeric is not null
        and pe.recorded_at::date between v_challenge.starts_on and v_challenge.ends_on
        and (
          (v_enrollment.scope='individual' and pe.contact_id=v_enrollment.contact_id)
          or
          (v_enrollment.scope='household' and pe.contact_id in (
            select hm.contact_id from public.household_members hm
            where hm.household_id=v_enrollment.household_id and hm.status='active'
          ))
        )
      order by pe.recorded_at desc
      limit 1
    ),0) into v_value;
  end if;

  v_percent := case
    when coalesce(v_challenge.target_value,0)<=0 then 0
    else least(100,greatest(0,round(100.0*v_value/v_challenge.target_value)::int))
  end;

  v_points := round(v_challenge.points_available * v_percent / 100.0)::int;

  update public.challenge_enrollments
  set current_value=v_value,
      completion_percent=v_percent,
      points_earned=v_points,
      status=case when v_percent>=100 then 'completed' else status end,
      completed_at=case when v_percent>=100 then coalesce(completed_at,now()) else completed_at end,
      updated_at=now()
  where id=v_enrollment.id;

  if v_percent>=100 and not v_was_completed then
    insert into public.challenge_activity(
      enrollment_id,contact_id,activity_type,value_delta,resulting_value,points_delta,source_type
    )
    values(
      v_enrollment.id,v_enrollment.contact_id,'challenge_completed',null,v_value,
      greatest(0,v_challenge.points_available-v_enrollment.points_earned),'progress_engine'
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_program_community_space(p_program_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_space_id uuid;
  v_name text;
begin
  select name into v_name
  from public.program_catalog
  where program_code=p_program_code;

  if v_name is null then return null; end if;

  insert into public.community_spaces(
    space_key,name,description,space_type,program_code,status,posting_mode
  )
  values(
    'program:'||p_program_code,
    v_name||' Community',
    'Private ReVitalized community for active '||v_name||' members.',
    'program',p_program_code,'active','staff_and_members'
  )
  on conflict (space_key) do update
  set name=excluded.name,description=excluded.description,status='active',updated_at=now()
  returning id into v_space_id;

  return v_space_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enroll_client_in_challenge(p_challenge_id uuid, p_contact_id uuid, p_scope text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_challenge public.wellness_challenges%rowtype;
  v_access public.client_access%rowtype;
  v_enrollment_id uuid;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  select * into v_challenge
  from public.wellness_challenges
  where id=p_challenge_id
    and status in ('published','active');

  if v_challenge.id is null then
    raise exception 'Published challenge not found';
  end if;

  select * into v_access
  from public.client_access
  where contact_id=p_contact_id
  limit 1;

  if v_access.contact_id is null then
    raise exception 'Client access record not found';
  end if;

  if p_scope='individual' then
    if v_challenge.scope not in ('individual','both') then
      raise exception 'This challenge is not available for individual enrollment';
    end if;

    insert into public.challenge_enrollments(
      challenge_id,contact_id,household_id,membership_id,scope,status,enrolled_by
    )
    values(
      v_challenge.id,p_contact_id,null,v_access.membership_id,'individual','active',(select auth.uid())
    )
    on conflict (challenge_id,contact_id) where scope='individual' and contact_id is not null
    do update set
      status='active',
      membership_id=excluded.membership_id,
      updated_at=now()
    returning id into v_enrollment_id;

  elsif p_scope='household' then
    if v_challenge.scope not in ('household','both') then
      raise exception 'This challenge is not available for household enrollment';
    end if;

    if v_access.household_id is null then
      raise exception 'This client does not have a ReVitalized household yet';
    end if;

    insert into public.challenge_enrollments(
      challenge_id,contact_id,household_id,membership_id,scope,status,enrolled_by
    )
    values(
      v_challenge.id,null,v_access.household_id,v_access.membership_id,'household','active',(select auth.uid())
    )
    on conflict (challenge_id,household_id) where scope='household' and household_id is not null
    do update set
      status='active',
      membership_id=excluded.membership_id,
      updated_at=now()
    returning id into v_enrollment_id;
  else
    raise exception 'Challenge enrollment scope must be individual or household';
  end if;

  perform private.recalculate_challenge_enrollment(v_enrollment_id);

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'challenge_enrolled','Challenge enrolled',v_challenge.title,(select auth.uid()),
    jsonb_build_object('challenge_id',v_challenge.id,'enrollment_id',v_enrollment_id,'scope',p_scope)
  );

  return v_enrollment_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_member_community_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user uuid;
  v_space uuid;
  v_household_space uuid;
begin
  if NEW.status<>'active' then return NEW; end if;

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=NEW.primary_contact_id and ca.status='active';

  if v_user is null then return NEW; end if;

  v_space := private.ensure_program_community_space(NEW.program_code);

  if v_space is not null then
    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_space,v_user,NEW.primary_contact_id,'member','active')
    on conflict (space_id,user_id) do update set
      contact_id=excluded.contact_id,status='active',left_at=null;
  end if;

  if NEW.household_id is not null then
    insert into public.community_spaces(
      space_key,name,description,space_type,household_id,status,posting_mode,created_by
    )
    select
      'household:'||NEW.household_id::text,
      coalesce(h.household_name,'ReVitalized Household'),
      'Private ReVitalized family space.',
      'household',NEW.household_id,'active','members',NEW.created_by
    from public.households h
    where h.id=NEW.household_id
    on conflict (space_key) do update set status='active',updated_at=now()
    returning id into v_household_space;

    insert into public.community_memberships(space_id,user_id,contact_id,membership_role,status)
    values(v_household_space,v_user,NEW.primary_contact_id,'owner','active')
    on conflict (space_id,user_id) do update set
      contact_id=excluded.contact_id,membership_role='owner',status='active',left_at=null;
  end if;

  return NEW;
end;
$function$

