CREATE OR REPLACE FUNCTION public.moderate_community_post(p_post_id uuid, p_action text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_post public.community_posts%rowtype;
  v_status text;
begin
  if not exists (
    select 1 from public.staff_access s
    where s.user_id=(select auth.uid())
      and s.role in ('owner','admin','coach')
  ) then
    raise exception 'Owner/Admin/Coach access required';
  end if;

  if p_action not in ('hide_post','remove_post','restore_post') then
    raise exception 'Invalid moderation action';
  end if;

  if trim(coalesce(p_reason,''))='' then
    raise exception 'Moderation reason is required';
  end if;

  select * into v_post from public.community_posts where id=p_post_id;
  if v_post.id is null then raise exception 'Post not found'; end if;

  v_status := case
    when p_action='hide_post' then 'hidden'
    when p_action='remove_post' then 'removed'
    else 'published'
  end;

  update public.community_posts
  set status=v_status,updated_at=now()
  where id=p_post_id;

  insert into public.community_moderation_events(
    space_id,post_id,action,reason,actor_user_id
  )
  values(v_post.space_id,v_post.id,p_action,trim(p_reason),(select auth.uid()));
end;
$function$

