CREATE OR REPLACE FUNCTION public.invite_contact_to_refuel(p_contact_id uuid, p_offer_id uuid, p_channel text, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_invitation_id uuid;
  v_offer public.refuel_offers%rowtype;
begin
  if not exists (
    select 1 from public.staff_access s where s.user_id=(select auth.uid())
  ) then
    raise exception 'Staff access required';
  end if;

  if p_channel not in ('email','sms','in_app','manual') then
    raise exception 'Invalid invitation channel';
  end if;

  select * into v_offer
  from public.refuel_offers
  where id=p_offer_id and status='published';

  if v_offer.id is null then
    raise exception 'Published ReFuel offer not found';
  end if;

  insert into public.refuel_invitations(
    contact_id,offer_id,status,invitation_channel,invited_by,invited_at,note
  )
  values(
    p_contact_id,p_offer_id,
    case when p_channel='manual' then 'sent' else 'queued' end,
    p_channel,(select auth.uid()),
    case when p_channel='manual' then now() else null end,
    p_note
  )
  on conflict (contact_id,offer_id) do update
  set status=case
        when public.refuel_invitations.status in ('accepted','declined') then public.refuel_invitations.status
        else excluded.status
      end,
      invitation_channel=excluded.invitation_channel,
      invited_by=excluded.invited_by,
      invited_at=coalesce(public.refuel_invitations.invited_at,excluded.invited_at),
      note=excluded.note,
      updated_at=now()
  returning id into v_invitation_id;

  update public.refuel_interest
  set status='notified',updated_at=now()
  where contact_id=p_contact_id
    and status='interested';

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'refuel_invited','ReFuel invitation created',v_offer.name,
    (select auth.uid()),
    jsonb_build_object('offer_id',p_offer_id,'invitation_id',v_invitation_id,'channel',p_channel)
  );

  return v_invitation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.enroll_contact_in_refuel(p_contact_id uuid, p_offer_id uuid, p_payment_status text DEFAULT 'pending'::text, p_amount_cents integer DEFAULT NULL::integer, p_currency text DEFAULT 'USD'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_offer public.refuel_offers%rowtype;
  v_access public.client_access%rowtype;
  v_invitation_id uuid;
  v_enrollment_id uuid;
  v_status text;
begin
  if not exists (
    select 1 from public.staff_access s
    where s.user_id=(select auth.uid())
      and s.role in ('owner','admin')
  ) then
    raise exception 'Owner/Admin access required';
  end if;

  if p_payment_status not in ('pending','paid','included','waived','failed','refunded') then
    raise exception 'Invalid ReFuel payment status';
  end if;

  select * into v_offer
  from public.refuel_offers
  where id=p_offer_id and status='published';

  if v_offer.id is null then
    raise exception 'Published ReFuel offer not found';
  end if;

  select * into v_access
  from public.client_access
  where contact_id=p_contact_id
  limit 1;

  select id into v_invitation_id
  from public.refuel_invitations
  where contact_id=p_contact_id and offer_id=p_offer_id
  limit 1;

  v_status := case
    when p_payment_status in ('paid','included','waived') then 'active'
    else 'pending'
  end;

  insert into public.refuel_enrollments(
    contact_id,membership_id,offer_id,invitation_id,status,payment_status,
    amount_cents,currency,enrolled_by,activated_at,notes
  )
  values(
    p_contact_id,v_access.membership_id,p_offer_id,v_invitation_id,v_status,p_payment_status,
    coalesce(p_amount_cents,v_offer.price_cents),coalesce(p_currency,v_offer.currency),
    (select auth.uid()),
    case when v_status='active' then now() else null end,
    p_notes
  )
  on conflict (contact_id,offer_id) do update
  set membership_id=excluded.membership_id,
      invitation_id=coalesce(excluded.invitation_id,public.refuel_enrollments.invitation_id),
      status=excluded.status,
      payment_status=excluded.payment_status,
      amount_cents=excluded.amount_cents,
      currency=excluded.currency,
      enrolled_by=excluded.enrolled_by,
      activated_at=case
        when excluded.status='active' then coalesce(public.refuel_enrollments.activated_at,now())
        else public.refuel_enrollments.activated_at
      end,
      notes=excluded.notes
  returning id into v_enrollment_id;

  if v_invitation_id is not null then
    update public.refuel_invitations
    set status='accepted',responded_at=coalesce(responded_at,now()),updated_at=now()
    where id=v_invitation_id;
  end if;

  update public.refuel_interest
  set status='converted',updated_at=now()
  where contact_id=p_contact_id;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,'refuel_enrolled','ReFuel enrollment updated',v_offer.name,
    (select auth.uid()),
    jsonb_build_object(
      'offer_id',p_offer_id,'enrollment_id',v_enrollment_id,
      'payment_status',p_payment_status,'status',v_status
    )
  );

  return v_enrollment_id;
end;
$function$

