CREATE OR REPLACE FUNCTION private.evaluate_engagement_achievements(p_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_membership_id uuid;
  v_checkins integer;
  v_challenges integer;
  v_courses integer;
begin
  select ca.membership_id
    into v_membership_id
  from public.client_access ca
  where ca.contact_id=p_contact_id
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  select count(*)::integer
    into v_checkins
  from public.habit_checkins hc
  where hc.contact_id=p_contact_id;

  select count(*)::integer
    into v_challenges
  from public.challenge_enrollments ce
  where ce.contact_id=p_contact_id
    and ce.status='completed';

  select count(*)::integer
    into v_courses
  from public.client_course_enrollments cce
  where cce.contact_id=p_contact_id
    and cce.status='completed';

  if v_checkins >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_checkin','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_checkins >= 7 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'seven_checkins','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_checkins >= 30 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'thirty_checkins','habit_checkin')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_challenges >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_challenge_complete','challenge')
    on conflict(contact_id,achievement_key) do nothing;
  end if;

  if v_courses >= 1 then
    insert into public.member_achievements(contact_id,membership_id,achievement_key,source_type)
    values(p_contact_id,v_membership_id,'first_course_complete','course')
    on conflict(contact_id,achievement_key) do nothing;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.ensure_referral_profile(p_contact_id uuid, p_user_id uuid DEFAULT NULL::uuid)
