CREATE OR REPLACE FUNCTION public.bulk_update_people(p_contact_ids uuid[], p_action text, p_value text, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_count integer := 0;
  v_id uuid;
  v_staff uuid;
begin
  if not private.staff_has_permission((select auth.uid()),'crm.manage') then
    raise exception 'CRM management permission required';
  end if;

  if p_contact_ids is null or array_length(p_contact_ids,1) is null then
    return 0;
  end if;

  if p_action='assign_staff' then
    v_staff := nullif(p_value,'')::uuid;
    update public.contacts
    set assigned_to=v_staff,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='set_stage' then
    if p_value not in ('lead','assessment_lead','webinar_lead','applicant','client','inactive') then
      raise exception 'Invalid lifecycle stage';
    end if;
    update public.contacts
    set lifecycle_stage=p_value,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='set_followup_status' then
    if p_value not in ('new','needs_follow_up','contacted','consultation_scheduled','consultation_completed','nurture','not_ready','closed') then
      raise exception 'Invalid follow-up status';
    end if;
    update public.contacts
    set follow_up_status=p_value,updated_at=now()
    where id=any(p_contact_ids);
    get diagnostics v_count=row_count;

  elsif p_action='add_tag' then
    if nullif(trim(p_value),'') is null then raise exception 'Tag is required'; end if;
    foreach v_id in array p_contact_ids loop
      insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
      values(v_id,lower(trim(p_value)),'manual','bulk-people',now())
      on conflict (contact_id,tag) do update set updated_at=now();
      v_count:=v_count+1;
    end loop;

  else
    raise exception 'Invalid bulk People action';
  end if;

  foreach v_id in array p_contact_ids loop
    insert into public.contact_activity(
      contact_id,activity_type,title,detail,actor_user_id,metadata
    )
    values(
      v_id,'bulk_people_update','People record updated in bulk',
      coalesce(nullif(trim(p_reason),''),'Bulk People Directory action'),
      (select auth.uid()),
      jsonb_build_object('action',p_action,'value',p_value)
    );
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_team_calendar_item(p_item_type text, p_item_id uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contact_id uuid;
  v_title text;
begin
  if p_status not in ('scheduled','completed','cancelled','no_show') then
    raise exception 'Invalid schedule status';
  end if;

  if p_item_type='journey_appointment' then
    if not private.staff_has_permission((select auth.uid()),'crm.manage') then
      raise exception 'CRM management permission required';
    end if;

    update public.journey_appointments
    set status=p_status,
        completed_at=case when p_status='completed' then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=p_item_id
    returning contact_id,appointment_type into v_contact_id,v_title;

  elsif p_item_type='coaching_session' then
    if not private.staff_has_permission((select auth.uid()),'coaching.manage') then
      raise exception 'Coaching management permission required';
    end if;

    update public.coaching_sessions
    set status=p_status,
        completed_at=case when p_status='completed' then coalesce(completed_at,now()) else completed_at end,
        updated_at=now()
    where id=p_item_id
    returning contact_id,'coaching_session' into v_contact_id,v_title;

  else
    raise exception 'Invalid calendar item type';
  end if;

  if v_contact_id is null then raise exception 'Calendar item not found'; end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    v_contact_id,
    'schedule_status_updated',
    'Schedule status updated',
    coalesce(nullif(trim(p_reason),''),initcap(replace(v_title,'_',' '))||' → '||initcap(replace(p_status,'_',' '))),
    (select auth.uid()),
    jsonb_build_object('item_type',p_item_type,'item_id',p_item_id,'status',p_status)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_membership_subscription(p_membership_id uuid, p_billing_plan_id uuid, p_provider text DEFAULT NULL::text, p_provider_customer_id text DEFAULT NULL::text, p_provider_subscription_id text DEFAULT NULL::text, p_status text DEFAULT 'pending'::text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_next_charge_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  m public.client_memberships%rowtype;
  p public.billing_plans%rowtype;
  v_id uuid;
  v_start timestamptz;
  v_commit_end timestamptz;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  if p_status not in ('pending','trialing','active','past_due','paused','cancelled','completed') then
    raise exception 'Invalid subscription status';
  end if;

  select * into m from public.client_memberships where id=p_membership_id;
  if m.id is null then raise exception 'Membership not found'; end if;

  select * into p from public.billing_plans where id=p_billing_plan_id and active;
  if p.id is null then raise exception 'Active billing plan not found'; end if;

  v_start:=coalesce(p_started_at,m.starts_at,now());
  v_commit_end:=case
    when p.commitment_months is not null then v_start+(p.commitment_months||' month')::interval
    else m.commitment_ends_at
  end;

  insert into public.membership_subscriptions(
    membership_id,contact_id,billing_plan_id,provider,provider_customer_id,
    provider_subscription_id,status,started_at,next_charge_at,
    commitment_ends_at,created_by
  )
  values(
    m.id,m.primary_contact_id,p.id,nullif(trim(p_provider),''),
    nullif(trim(p_provider_customer_id),''),
    nullif(trim(p_provider_subscription_id),''),
    p_status,v_start,p_next_charge_at,v_commit_end,(select auth.uid())
  )
  on conflict (membership_id) do update
  set billing_plan_id=excluded.billing_plan_id,
      provider=coalesce(excluded.provider,public.membership_subscriptions.provider),
      provider_customer_id=coalesce(excluded.provider_customer_id,public.membership_subscriptions.provider_customer_id),
      provider_subscription_id=coalesce(excluded.provider_subscription_id,public.membership_subscriptions.provider_subscription_id),
      status=excluded.status,
      started_at=coalesce(public.membership_subscriptions.started_at,excluded.started_at),
      next_charge_at=excluded.next_charge_at,
      commitment_ends_at=excluded.commitment_ends_at,
      updated_at=now()
  returning id into v_id;

  update public.client_memberships
  set billing_choice=p.billing_interval,
      amount_cents=p.amount_cents,
      currency=p.currency,
      commitment_months=coalesce(p.commitment_months,commitment_months),
      commitment_ends_at=coalesce(v_commit_end,commitment_ends_at),
      updated_at=now()
  where id=m.id;

  insert into public.billing_events(
    subscription_id,membership_id,contact_id,event_type,provider,status,occurred_at,recorded_by
  )
  values(
    v_id,m.id,m.primary_contact_id,'subscription_created',
    nullif(trim(p_provider),''),p_status,now(),(select auth.uid())
  );

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.handle_billing_failure_workflow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user uuid;
  v_assignee uuid;
  v_sub public.membership_subscriptions%rowtype;
  v_plan public.billing_plans%rowtype;
  v_due timestamptz;
begin
  if NEW.event_type<>'payment_failed' then return NEW; end if;

  select * into v_sub from public.membership_subscriptions where id=NEW.subscription_id;
  select * into v_plan from public.billing_plans where id=v_sub.billing_plan_id;

  v_due:=coalesce(v_sub.grace_period_ends_at,NEW.occurred_at+coalesce(v_plan.grace_days,3)*interval '1 day');

  select ca.user_id into v_user
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.status='active'
    and ca.user_id is not null
  limit 1;

  if v_user is not null then
    insert into public.member_notifications(
      user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
    )
    values(
      v_user,NEW.contact_id,'billing_alert',
      'Membership payment needs attention',
      'We were unable to process your ReVitalized membership payment. Please review your billing information or contact the ReVitalized team before the grace period ends.',
      '/member/','billing_payment_failure',NEW.id
    )
    on conflict (user_id,notification_type,source_type,source_id)
      where source_id is not null
    do nothing;
  end if;

  select sa.user_id into v_assignee
  from public.staff_access sa
  where sa.status='active'
    and private.staff_has_permission(sa.user_id,'finance.manage')
  order by
    case sa.role when 'financial' then 1 when 'owner' then 2 when 'admin' then 3 else 4 end,
    sa.created_at
  limit 1;

  if not exists(
    select 1 from public.follow_up_tasks t
    where t.contact_id=NEW.contact_id
      and t.title='Resolve past-due membership payment'
      and t.status='open'
  ) then
    insert into public.follow_up_tasks(
      contact_id,assigned_to,title,due_at,status,priority,task_type,instructions
    )
    values(
      NEW.contact_id,v_assignee,'Resolve past-due membership payment',
      v_due,'open','high','billing',
      'Review the failed membership payment, contact the client if needed, and resolve billing before the grace period ends.'
    );
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,metadata
  )
  values(
    NEW.contact_id,'billing_payment_failed','Membership payment failed',
    'Billing recovery workflow started.',
    jsonb_build_object('billing_event_id',NEW.id,'subscription_id',NEW.subscription_id,'grace_period_ends_at',v_due)
  );

  return NEW;
end;
$function$

