CREATE OR REPLACE FUNCTION private.backfill_agreement_requirement_record(p_requirement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  r public.program_agreement_requirements%rowtype;
  t public.agreement_templates%rowtype;
  m record;
begin
  select * into r from public.program_agreement_requirements where id=p_requirement_id;
  if r.id is null or not r.active or not r.required then return; end if;

  select * into t from public.agreement_templates where id=r.agreement_template_id and status='published';
  if t.id is null then return; end if;

  for m in
    select cm.*
    from public.client_memberships cm
    where cm.program_code=r.program_code
      and cm.status in ('pending','active')
  loop
    insert into public.client_agreements(
      contact_id,membership_id,activation_id,agreement_template_id,
      agreement_key,template_version,content_hash,status,created_by
    )
    values(
      m.primary_contact_id,m.id,m.activation_id,t.id,
      t.agreement_key,t.version,t.content_hash,'not_sent',m.created_by
    )
    on conflict (contact_id,agreement_template_id) do update
    set membership_id=excluded.membership_id,
        activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
        updated_at=now();
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_client_agreement(p_contact_id uuid, p_agreement_template_id uuid, p_send boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.agreement_templates%rowtype;
  m public.client_memberships%rowtype;
  a public.client_agreements%rowtype;
  v_user uuid;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  select * into t
  from public.agreement_templates
  where id=p_agreement_template_id
    and status='published';

  if t.id is null then raise exception 'Published agreement template not found'; end if;

  select * into m
  from public.client_memberships
  where primary_contact_id=p_contact_id
  order by created_at desc
  limit 1;

  if m.id is null then raise exception 'Client membership not found'; end if;

  insert into public.client_agreements(
    contact_id,membership_id,activation_id,agreement_template_id,
    agreement_key,template_version,content_hash,status,sent_at,created_by
  )
  values(
    p_contact_id,m.id,m.activation_id,t.id,t.agreement_key,t.version,t.content_hash,
    case when p_send then 'sent' else 'not_sent' end,
    case when p_send then now() else null end,
    (select auth.uid())
  )
  on conflict (contact_id,agreement_template_id) do update
  set membership_id=excluded.membership_id,
      activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
      status=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.status
        when p_send then 'sent'
        else public.client_agreements.status
      end,
      sent_at=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.sent_at
        when p_send then now()
        else public.client_agreements.sent_at
      end,
      updated_at=now()
  returning * into a;

  if p_send and a.status='sent' then
    select ca.user_id into v_user
    from public.client_access ca
    where ca.contact_id=p_contact_id and ca.status='active' and ca.user_id is not null
    limit 1;

    if v_user is not null then
      insert into public.member_notifications(
        user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
      )
      values(
        v_user,p_contact_id,'program_update',
        'Agreement ready for your review',
        t.name||' is ready to review and sign in your ReVitalized member dashboard.',
        '/member/','client_agreement',a.id
      )
      on conflict (user_id,notification_type,source_type,source_id)
        where source_id is not null
      do nothing;
    end if;
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,
    case when p_send then 'agreement_sent' else 'agreement_assigned' end,
    case when p_send then 'Agreement sent' else 'Agreement assigned' end,
    t.name||' · v'||t.version,
    (select auth.uid()),
    jsonb_build_object('client_agreement_id',a.id,'template_id',t.id)
  );

  return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.waive_client_agreement(p_client_agreement_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.client_agreements%rowtype;
  v_role text;
begin
  select role into v_role
  from public.staff_access
  where user_id=(select auth.uid())
    and status='active';

  if v_role not in ('owner','admin') then
    raise exception 'Only Owner/Admin can waive a client agreement';
  end if;

  if nullif(trim(p_reason),'') is null then
    raise exception 'Waiver reason is required';
  end if;

  select * into a from public.client_agreements where id=p_client_agreement_id;
  if a.id is null then raise exception 'Client agreement not found'; end if;
  if a.status='signed' then raise exception 'Signed agreements cannot be waived'; end if;

  update public.client_agreements
  set status='waived',
      waived_at=now(),
      waived_by=(select auth.uid()),
      waiver_reason=trim(p_reason),
      updated_at=now()
  where id=a.id;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    a.contact_id,'agreement_waived','Agreement requirement waived',
    trim(p_reason),(select auth.uid()),
    jsonb_build_object('client_agreement_id',a.id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_coaching_session_entitlement()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_entitlement_id uuid;
  v_new_status text;
  v_review_reason text;
begin
  if NEW.membership_id is null then
    return NEW;
  end if;

  select id into v_entitlement_id
  from public.membership_entitlements
  where membership_id=NEW.membership_id
    and entitlement_key='private_coaching'
    and status='active'
  limit 1;

  -- The ledger can still track a session when there is not yet a numeric limit.
  if NEW.status='scheduled' then
    v_new_status:='reserved';
  elsif NEW.status='completed' then
    v_new_status:='consumed';
  elsif NEW.status='cancelled' then
    v_new_status:='released';
  elsif NEW.status='no_show' then
    v_new_status:='review';
    v_review_reason:='No-show requires staff determination before consuming or releasing an entitlement.';
  else
    return NEW;
  end if;

  insert into public.coaching_entitlement_usage(
    membership_id,entitlement_id,coaching_session_id,contact_id,
    entitlement_key,usage_units,status,reserved_at,consumed_at,released_at,review_reason
  )
  values(
    NEW.membership_id,v_entitlement_id,NEW.id,NEW.contact_id,
    'private_coaching',1,v_new_status,
    case when v_new_status='reserved' then coalesce(NEW.created_at,now()) else null end,
    case when v_new_status='consumed' then coalesce(NEW.completed_at,now()) else null end,
    case when v_new_status='released' then now() else null end,
    v_review_reason
  )
  on conflict (coaching_session_id) do update
  set entitlement_id=coalesce(excluded.entitlement_id,public.coaching_entitlement_usage.entitlement_id),
      status=excluded.status,
      reserved_at=case
        when excluded.status='reserved' then coalesce(public.coaching_entitlement_usage.reserved_at,now())
        else public.coaching_entitlement_usage.reserved_at
      end,
      consumed_at=case when excluded.status='consumed' then coalesce(public.coaching_entitlement_usage.consumed_at,now()) else null end,
      released_at=case when excluded.status='released' then coalesce(public.coaching_entitlement_usage.released_at,now()) else null end,
      review_reason=excluded.review_reason,
      updated_at=now();

  perform private.recalculate_coaching_entitlement_used_value(NEW.membership_id,'private_coaching');

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.notify_member_challenge_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
begin
  if NEW.status<>'completed' or NEW.contact_id is null then
    return NEW;
  end if;

  if TG_OP='UPDATE' and OLD.status='completed' then
    return NEW;
  end if;

  select ca.user_id
  into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.contact_id
    and ca.user_id is not null
  limit 1;

  if v_user_id is null then
    return NEW;
  end if;

  select wc.title
  into v_title
  from public.wellness_challenges wc
  where wc.id=NEW.challenge_id;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,
    NEW.contact_id,
    'challenge_completed',
    'Challenge completed',
    coalesce(v_title,'You completed a ReVitalized challenge.'),
    'unread',
    'challenge',
    NEW.challenge_id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do nothing;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_my_message(p_conversation_id uuid, p_body text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_id uuid;
begin
  if coalesce(length(trim(p_body)),0)<1 or length(trim(p_body))>8000 then
    raise exception 'Message must be between 1 and 8000 characters';
  end if;

  if not private.current_user_is_conversation_participant(p_conversation_id) then
    raise exception 'Conversation is not available';
  end if;

  select ca.contact_id
  into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
  limit 1;

  insert into public.member_messages(
    conversation_id,sender_user_id,sender_contact_id,body,message_type
  )
  values(
    p_conversation_id,(select auth.uid()),v_contact_id,trim(p_body),'text'
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_coaching_entitlement_review(p_usage_id uuid, p_resolution text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  u public.coaching_entitlement_usage%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'coaching.manage') then
    raise exception 'Coaching management permission required';
  end if;

  if p_resolution not in ('consumed','released') then
    raise exception 'Resolution must be consumed or released';
  end if;

  if nullif(trim(p_reason),'') is null then
    raise exception 'Resolution reason is required';
  end if;

  select * into u from public.coaching_entitlement_usage where id=p_usage_id;
  if u.id is null then raise exception 'Entitlement usage record not found'; end if;

  update public.coaching_entitlement_usage
  set status=p_resolution,
      consumed_at=case when p_resolution='consumed' then now() else null end,
      released_at=case when p_resolution='released' then now() else null end,
      review_reason=trim(p_reason),
      updated_by=(select auth.uid()),
      updated_at=now()
  where id=u.id;

  perform private.recalculate_coaching_entitlement_used_value(u.membership_id,u.entitlement_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.import_people_batch(p_rows jsonb, p_filename text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_batch_id uuid;
  v_row jsonb;
  v_index integer:=0;
  v_total integer:=0;
  v_created integer:=0;
  v_updated integer:=0;
  v_skipped integer:=0;
  v_errors integer:=0;
  v_error_list jsonb:='[]'::jsonb;
  v_contact_id uuid;
  v_email text;
  v_phone text;
  v_phone_digits text;
  v_stage text;
  v_source text;
  v_first text;
  v_last text;
  v_city text;
  v_state text;
  v_country text;
  v_tags text[];
  v_tag text;
begin
  if not private.staff_has_permission((select auth.uid()),'people.import') then
    raise exception 'People import permission required';
  end if;

  if jsonb_typeof(p_rows)<>'array' then
    raise exception 'Import rows must be a JSON array';
  end if;

  v_total:=jsonb_array_length(p_rows);
  if v_total>5000 then
    raise exception 'A single import is limited to 5,000 rows';
  end if;

  insert into public.people_import_batches(uploaded_by,filename,total_rows)
  values((select auth.uid()),nullif(trim(p_filename),''),v_total)
  returning id into v_batch_id;

  for v_row in select * from jsonb_array_elements(p_rows)
  loop
    v_index:=v_index+1;
    begin
      v_first:=nullif(trim(coalesce(v_row->>'first_name','')),'');
      v_last:=nullif(trim(coalesce(v_row->>'last_name','')),'');
      v_email:=nullif(lower(trim(coalesce(v_row->>'email',''))),'');
      v_phone:=nullif(trim(coalesce(v_row->>'phone','')),'');
      v_city:=nullif(trim(coalesce(v_row->>'city','')),'');
      v_state:=nullif(trim(coalesce(v_row->>'state','')),'');
      v_country:=nullif(trim(coalesce(v_row->>'country','')),'');
      v_stage:=coalesce(nullif(trim(v_row->>'lifecycle_stage'),''),'lead');
      v_source:=coalesce(nullif(trim(v_row->>'source'),''),'csv_import');

      if v_first is null and v_last is null then
        raise exception 'First name or last name is required';
      end if;
      if v_email is null and v_phone is null then
        raise exception 'Email or phone is required';
      end if;
      if v_stage not in ('lead','assessment_lead','webinar_lead','applicant','client','inactive') then
        raise exception 'Invalid lifecycle stage: %',v_stage;
      end if;

      v_contact_id:=null;

      if v_email is not null then
        select id into v_contact_id
        from public.contacts
        where lower(email)=v_email
        limit 1;
      end if;

      if v_contact_id is null and v_phone is not null then
        v_phone_digits:=regexp_replace(v_phone,'[^0-9]','','g');
        select id into v_contact_id
        from public.contacts
        where phone is not null
          and regexp_replace(phone,'[^0-9]','','g')=v_phone_digits
        limit 1;
      end if;

      if v_contact_id is null then
        insert into public.contacts(
          first_name,last_name,email,phone,city,state,country,lifecycle_stage,
          first_source,last_source,follow_up_status,consultation_status,record_kind
        )
        values(
          v_first,v_last,v_email,v_phone,v_city,v_state,v_country,v_stage,
          v_source,v_source,'new','not_scheduled','crm'
        )
        returning id into v_contact_id;
        v_created:=v_created+1;
      else
        update public.contacts
        set first_name=coalesce(v_first,first_name),
            last_name=coalesce(v_last,last_name),
            email=coalesce(v_email,email),
            phone=coalesce(v_phone,phone),
            city=coalesce(v_city,city),
            state=coalesce(v_state,state),
            country=coalesce(v_country,country),
            lifecycle_stage=case when record_kind='crm' then v_stage else lifecycle_stage end,
            last_source=v_source,
            updated_at=now()
        where id=v_contact_id;
        v_updated:=v_updated+1;
      end if;

      if jsonb_typeof(v_row->'tags')='array' then
        select array_agg(value) into v_tags
        from jsonb_array_elements_text(v_row->'tags');
      else
        v_tags:=string_to_array(coalesce(v_row->>'tags',''),',');
      end if;

      if v_tags is not null then
        foreach v_tag in array v_tags loop
          if nullif(trim(v_tag),'') is not null then
            insert into public.contact_tags(contact_id,tag,source,rule_key,updated_at)
            values(v_contact_id,lower(trim(v_tag)),'csv_import','csv-import',now())
            on conflict (contact_id,tag) do update set updated_at=now();
          end if;
        end loop;
      end if;

      insert into public.contact_activity(
        contact_id,activity_type,title,detail,actor_user_id,metadata
      )
      values(
        v_contact_id,'csv_imported','People record imported',
        coalesce(nullif(trim(p_filename),''),'CSV import'),
        (select auth.uid()),
        jsonb_build_object('batch_id',v_batch_id,'row_number',v_index)
      );

    exception when others then
      v_errors:=v_errors+1;
      v_error_list:=v_error_list||jsonb_build_array(jsonb_build_object(
        'row',v_index,'error',sqlerrm,'data',v_row
      ));
    end;
  end loop;

  update public.people_import_batches
  set created_rows=v_created,
      updated_rows=v_updated,
      skipped_rows=v_skipped,
      error_rows=v_errors,
      errors=v_error_list,
      status=case when v_errors=0 then 'completed' else 'completed_with_errors' end,
      completed_at=now()
  where id=v_batch_id;

  return jsonb_build_object(
    'batch_id',v_batch_id,
    'total_rows',v_total,
    'created_rows',v_created,
    'updated_rows',v_updated,
    'skipped_rows',v_skipped,
    'error_rows',v_errors,
    'errors',v_error_list
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.render_agreement_content(p_template text, p_values jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_result text:=coalesce(p_template,'');
  r record;
begin
  for r in
    select key,value
    from jsonb_each_text(coalesce(p_values,'{}'::jsonb))
  loop
    v_result:=replace(v_result,'{{'||r.key||'}}',coalesce(r.value,''));
  end loop;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_program_challenge_to_existing_members()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_program_code text;
  v_membership_id uuid;
begin
  v_program_code:=coalesce(NEW.program_code,OLD.program_code);

  for v_membership_id in
    select cm.id
    from public.client_memberships cm
    where cm.program_code=v_program_code
  loop
    perform private.reconcile_membership_challenge_access(v_membership_id);
  end loop;

  if TG_OP='UPDATE' and OLD.program_code is distinct from NEW.program_code then
    for v_membership_id in
      select cm.id
      from public.client_memberships cm
      where cm.program_code=OLD.program_code
    loop
      perform private.reconcile_membership_challenge_access(v_membership_id);
    end loop;
  end if;

  return coalesce(NEW,OLD);
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_client_contract(p_contact_id uuid, p_agreement_template_id uuid, p_merge_values jsonb, p_send boolean DEFAULT true)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.agreement_templates%rowtype;
  m public.client_memberships%rowtype;
  a public.client_agreements%rowtype;
  v_rendered text;
  v_hash text;
  v_user uuid;
  v_required_signatures integer:=1;
begin
  if not private.staff_has_permission((select auth.uid()),'finance.manage') then
    raise exception 'Financial management permission required';
  end if;

  select * into t
  from public.agreement_templates
  where id=p_agreement_template_id
    and status='published'
    and audience='client';

  if t.id is null then raise exception 'Published client agreement template not found'; end if;

  perform private.validate_agreement_merge_values(t.merge_schema,p_merge_values);

  select * into m
  from public.client_memberships
  where primary_contact_id=p_contact_id
  order by created_at desc
  limit 1;

  if m.id is null then raise exception 'Client membership not found'; end if;

  v_rendered:=private.render_agreement_content(t.content_text,p_merge_values);
  v_hash:=encode(extensions.digest(convert_to(v_rendered,'UTF8'),'sha256'),'hex');

  if nullif(trim(coalesce(p_merge_values->>'secondary_client_name','')),'') is not null then
    v_required_signatures:=2;
  end if;

  insert into public.client_agreements(
    contact_id,membership_id,activation_id,agreement_template_id,
    agreement_key,template_version,content_hash,status,sent_at,created_by,
    merge_values,rendered_content_text,rendered_content_hash,
    company_approved_by,company_approved_at,company_approver_name,
    required_client_signatures
  )
  values(
    p_contact_id,m.id,m.activation_id,t.id,t.agreement_key,t.version,t.content_hash,
    case when p_send then 'sent' else 'not_sent' end,
    case when p_send then now() else null end,
    (select auth.uid()),
    coalesce(p_merge_values,'{}'::jsonb),v_rendered,v_hash,
    (select auth.uid()),now(),
    (select display_name from public.staff_access where user_id=(select auth.uid())),
    v_required_signatures
  )
  on conflict (contact_id,agreement_template_id) do update
  set membership_id=excluded.membership_id,
      activation_id=coalesce(excluded.activation_id,public.client_agreements.activation_id),
      merge_values=excluded.merge_values,
      rendered_content_text=excluded.rendered_content_text,
      rendered_content_hash=excluded.rendered_content_hash,
      required_client_signatures=excluded.required_client_signatures,
      company_approved_by=excluded.company_approved_by,
      company_approved_at=excluded.company_approved_at,
      company_approver_name=excluded.company_approver_name,
      status=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.status
        when p_send then 'sent'
        else 'not_sent'
      end,
      sent_at=case
        when public.client_agreements.status in ('signed','waived') then public.client_agreements.sent_at
        when p_send then now()
        else null
      end,
      updated_at=now()
  returning * into a;

  if p_send and a.status='sent' then
    select ca.user_id into v_user
    from public.client_access ca
    where ca.contact_id=p_contact_id and ca.status='active' and ca.user_id is not null
    limit 1;

    if v_user is not null then
      insert into public.member_notifications(
        user_id,contact_id,notification_type,title,body,link_url,source_type,source_id
      )
      values(
        v_user,p_contact_id,'program_update',
        'Your ReVitalized Academy contract is ready',
        'Your personalized ReVitalized Academy contract is ready to review and sign.',
        '/member/','client_contract',a.id
      )
      on conflict (user_id,notification_type,source_type,source_id)
        where source_id is not null
      do nothing;
    end if;
  end if;

  insert into public.contact_activity(
    contact_id,activity_type,title,detail,actor_user_id,metadata
  )
  values(
    p_contact_id,
    case when p_send then 'client_contract_sent' else 'client_contract_prepared' end,
    case when p_send then 'Client contract sent' else 'Client contract prepared' end,
    t.name||' · v'||t.version,
    (select auth.uid()),
    jsonb_build_object(
      'client_agreement_id',a.id,
      'template_id',t.id,
      'merge_values',p_merge_values
    )
  );

  return a.id;
end;
$function$

CREATE OR REPLACE FUNCTION private.issue_required_coach_nda()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'extensions'
AS $function$
declare
  t public.agreement_templates%rowtype;
  v_email text;
  v_rendered text;
  v_hash text;
  v_values jsonb;
  v_approver uuid;
  v_approver_name text;
begin
  if NEW.role<>'coach' or NEW.status<>'active' then
    return NEW;
  end if;

  select * into t
  from public.agreement_templates
  where audience='staff'
    and document_type='coach_nda'
    and status='published'
  order by published_at desc nulls last,created_at desc
  limit 1;

  if t.id is null then return NEW; end if;

  select email into v_email from auth.users where id=NEW.user_id;
  v_approver:=NEW.updated_by;
  select display_name into v_approver_name
  from public.staff_access
  where user_id=v_approver;

  v_values:=jsonb_build_object(
    'effective_date',to_char(current_date,'FMMonth DD, YYYY'),
    'recipient_name',NEW.display_name,
    'recipient_email',coalesce(v_email,'')
  );

  v_rendered:=private.render_agreement_content(t.content_text,v_values);
  v_hash:=encode(digest(convert_to(v_rendered,'UTF8'),'sha256'),'hex');

  insert into public.staff_agreements(
    staff_user_id,agreement_template_id,agreement_key,template_version,
    content_hash,rendered_content_text,rendered_content_hash,merge_values,
    status,required,sent_at,created_by,
    company_approved_by,company_approved_at,company_approver_name
  )
  values(
    NEW.user_id,t.id,t.agreement_key,t.version,t.content_hash,
    v_rendered,v_hash,v_values,'sent',true,now(),v_approver,
    v_approver,now(),coalesce(v_approver_name,'Authorized ReVitalized Representative')
  )
  on conflict (staff_user_id,agreement_template_id) do update
  set company_approved_by=coalesce(public.staff_agreements.company_approved_by,excluded.company_approved_by),
      company_approved_at=coalesce(public.staff_agreements.company_approved_at,excluded.company_approved_at),
      company_approver_name=coalesce(public.staff_agreements.company_approver_name,excluded.company_approver_name),
      updated_at=now();

  update public.staff_access
  set onboarding_status='pending',updated_at=now()
  where user_id=NEW.user_id;

  return NEW;
end;
$function$

