CREATE OR REPLACE FUNCTION private.notification_scheduled_for(p_user_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_enabled boolean;
  v_start time;
  v_end time;
  v_tz text;
  v_local_now timestamp;
  v_local_date date;
  v_local_time time;
  v_target_local timestamp;
begin
  select
    np.quiet_hours_enabled,
    np.quiet_hours_start,
    np.quiet_hours_end,
    case
      when np.time_zone is not null
       and exists(select 1 from pg_timezone_names where name=np.time_zone)
      then np.time_zone
      else 'UTC'
    end
  into v_enabled,v_start,v_end,v_tz
  from public.notification_preferences np
  where np.user_id=p_user_id;

  if not coalesce(v_enabled,false) or v_start is null or v_end is null or v_start=v_end then
    return now();
  end if;

  v_local_now := now() at time zone v_tz;
  v_local_date := v_local_now::date;
  v_local_time := v_local_now::time;

  if v_start < v_end then
    if v_local_time >= v_start and v_local_time < v_end then
      v_target_local := v_local_date + v_end;
      return v_target_local at time zone v_tz;
    end if;
  else
    if v_local_time >= v_start then
      v_target_local := (v_local_date + 1) + v_end;
      return v_target_local at time zone v_tz;
    elsif v_local_time < v_end then
      v_target_local := v_local_date + v_end;
      return v_target_local at time zone v_tz;
    end if;
  end if;

  return now();
end;
$function$

