CREATE OR REPLACE FUNCTION public.record_my_progress(p_metric_key text, p_value_numeric numeric DEFAULT NULL::numeric, p_value_boolean boolean DEFAULT NULL::boolean, p_note text DEFAULT NULL::text, p_recorded_at timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_type text;
  v_min numeric;
  v_max numeric;
  v_id uuid;
begin
  select pmc.value_type,pmc.minimum_value,pmc.maximum_value
  into v_type,v_min,v_max
  from public.progress_metric_catalog pmc
  where pmc.metric_key=p_metric_key
    and pmc.active
    and pmc.member_trackable
  limit 1;

  if v_type is null then
    raise exception 'Metric is not available for member tracking';
  end if;

  if v_type='boolean' then
    if p_value_boolean is null or p_value_numeric is not null then
      raise exception 'This metric requires a boolean value';
    end if;
  else
    if p_value_numeric is null or p_value_boolean is not null then
      raise exception 'This metric requires a numeric value';
    end if;
    if v_min is not null and p_value_numeric<v_min then
      raise exception 'Value is below the allowed minimum';
    end if;
    if v_max is not null and p_value_numeric>v_max then
      raise exception 'Value is above the allowed maximum';
    end if;
  end if;

  select ca.contact_id,ca.membership_id
  into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,value_boolean,recorded_at,
    source,created_by,note
  )
  values(
    v_contact_id,v_membership_id,p_metric_key,p_value_numeric,p_value_boolean,
    coalesce(p_recorded_at,now()),'member',(select auth.uid()),nullif(trim(p_note),'')
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_lesson_progress(p_enrollment_id uuid, p_lesson_id uuid, p_status text DEFAULT 'in_progress'::text, p_progress_seconds integer DEFAULT 0, p_completion_percent integer DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_id uuid;
  v_percent integer;
  v_status text;
begin
  if p_status not in ('not_started','in_progress','completed') then
    raise exception 'Unsupported lesson status';
  end if;

  if coalesce(p_progress_seconds,0)<0 then
    raise exception 'Progress seconds cannot be negative';
  end if;

  v_percent := greatest(0,least(100,coalesce(p_completion_percent,0)));
  v_status := p_status;

  if v_percent>=100 then
    v_status := 'completed';
  elsif v_percent>0 and v_status='not_started' then
    v_status := 'in_progress';
  end if;

  select cce.contact_id
  into v_contact_id
  from public.client_course_enrollments cce
  join public.client_access ca on ca.contact_id=cce.contact_id
  join public.learning_lessons ll on ll.id=p_lesson_id
  join public.learning_modules lm on lm.id=ll.module_id
  where cce.id=p_enrollment_id
    and ca.user_id=(select auth.uid())
    and cce.course_id=lm.course_id
    and cce.status in ('active','completed')
    and ll.status='published'
  limit 1;

  if v_contact_id is null then
    raise exception 'Lesson is not available in this enrollment';
  end if;

  insert into public.lesson_progress(
    enrollment_id,contact_id,lesson_id,status,progress_seconds,completion_percent,
    first_started_at,last_activity_at,completed_at,created_by
  )
  values(
    p_enrollment_id,v_contact_id,p_lesson_id,v_status,
    coalesce(p_progress_seconds,0),v_percent,
    case when v_status<>'not_started' then now() else null end,
    now(),
    case when v_status='completed' then now() else null end,
    (select auth.uid())
  )
  on conflict (enrollment_id,lesson_id) do update
  set status=excluded.status,
      progress_seconds=greatest(public.lesson_progress.progress_seconds,excluded.progress_seconds),
      completion_percent=greatest(public.lesson_progress.completion_percent,excluded.completion_percent),
      first_started_at=coalesce(public.lesson_progress.first_started_at,excluded.first_started_at),
      last_activity_at=now(),
      completed_at=case
        when excluded.status='completed'
        then coalesce(public.lesson_progress.completed_at,now())
        else public.lesson_progress.completed_at
      end,
      created_by=coalesce(public.lesson_progress.created_by,(select auth.uid()))
  returning id into v_id;

  return v_id;
end;
$function$

