CREATE OR REPLACE FUNCTION private.notify_referrer_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_first_name text;
  v_title text;
  v_body text;
begin
  if NEW.referrer_contact_id is null then return NEW; end if;
  if NEW.status not in ('engaged','applicant','converted') then return NEW; end if;
  if TG_OP='UPDATE' and OLD.status=NEW.status then return NEW; end if;

  select ca.user_id into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.referrer_contact_id
    and ca.user_id is not null
    and ca.status='active'
  limit 1;

  if v_user_id is null then return NEW; end if;

  select c.first_name into v_first_name
  from public.contacts c
  where c.id=NEW.referred_contact_id;

  v_title:=case NEW.status
    when 'engaged' then 'Your referral is exploring ReVitalized'
    when 'applicant' then 'Your referral took the next step'
    when 'converted' then 'Your referral joined ReVitalized'
  end;

  v_body:=coalesce(v_first_name,'Someone you referred');

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,NEW.referrer_contact_id,'referral_'||NEW.status,
    v_title,v_body,'unread','referral',NEW.id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do nothing;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.notify_referral_reward_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_user_id uuid;
  v_title text;
  v_body text;
begin
  if NEW.status not in ('approved','issued') then return NEW; end if;
  if TG_OP='UPDATE' and OLD.status=NEW.status then return NEW; end if;

  select ca.user_id into v_user_id
  from public.client_access ca
  where ca.contact_id=NEW.referrer_contact_id
    and ca.user_id is not null
    and ca.status='active'
  limit 1;

  if v_user_id is null then return NEW; end if;

  v_title:=case NEW.status
    when 'approved' then 'Referral reward approved'
    when 'issued' then 'Referral reward issued'
  end;

  v_body:=case
    when NEW.reward_value is not null
      then trim(to_char(NEW.reward_value,'FM999999990.00'))||
           case when NEW.currency is not null then ' '||NEW.currency else '' end
    else initcap(NEW.reward_type)
  end;

  insert into public.member_notifications(
    user_id,contact_id,notification_type,title,body,status,source_type,source_id
  )
  values(
    v_user_id,NEW.referrer_contact_id,'referral_reward_'||NEW.status,
    v_title,v_body,'unread','referral_reward',NEW.id
  )
  on conflict (user_id,notification_type,source_type,source_id)
    where source_id is not null
  do nothing;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.create_family_change_request(p_user_id uuid, p_request_type text, p_target_household_member_id uuid, p_first_name text, p_last_name text, p_relationship_type text, p_sex text, p_date_of_birth date, p_email text, p_notes text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_membership_id uuid;
  v_family_limit integer;
  v_active_members integer;
  v_open_adds integer;
  v_id uuid;
begin
  if p_request_type not in ('add_member','remove_member','update_member') then
    raise exception 'Unsupported family request type';
  end if;

  select ca.contact_id,ca.household_id,ca.membership_id
  into v_contact_id,v_household_id,v_membership_id
  from public.client_access ca
  where ca.user_id=p_user_id
    and ca.status='active'
  limit 1;

  if v_contact_id is null or v_membership_id is null then
    raise exception 'Active member access is required';
  end if;

  select me.limit_value
  into v_family_limit
  from public.membership_entitlements me
  where me.membership_id=v_membership_id
    and me.entitlement_key='family_profiles'
    and me.status='active'
  limit 1;

  if v_family_limit is null then
    raise exception 'Family Hub is not included with this membership';
  end if;

  if p_request_type='add_member' then
    if coalesce(trim(p_first_name),'')='' then
      raise exception 'First name is required';
    end if;

    if p_relationship_type not in ('husband','wife','child','dependent') then
      raise exception 'Choose a valid family relationship';
    end if;

    if p_sex not in ('male','female') then
      raise exception 'Sex must be male or female';
    end if;

    if p_relationship_type='husband' and p_sex<>'male' then
      raise exception 'A husband must be recorded as male';
    end if;

    if p_relationship_type='wife' and p_sex<>'female' then
      raise exception 'A wife must be recorded as female';
    end if;

    select count(*)
    into v_active_members
    from public.household_members hm
    where hm.household_id=v_household_id
      and hm.status='active';

    select count(*)
    into v_open_adds
    from public.family_change_requests fcr
    where fcr.household_id=v_household_id
      and fcr.request_type='add_member'
      and fcr.status in ('submitted','in_review','approved');

    if v_active_members+v_open_adds>=v_family_limit then
      raise exception 'This membership has reached its Family Hub profile limit';
    end if;
  else
    if p_target_household_member_id is null then
      raise exception 'Choose the family member to update';
    end if;

    if not exists(
      select 1
      from public.household_members hm
      where hm.id=p_target_household_member_id
        and hm.household_id=v_household_id
        and hm.status='active'
        and not hm.is_primary
    ) then
      raise exception 'That family member is not available for this request';
    end if;
  end if;

  insert into public.family_change_requests(
    user_id,contact_id,household_id,membership_id,request_type,
    target_household_member_id,first_name,last_name,relationship_type,sex,
    date_of_birth,email,notes,status
  )
  values(
    p_user_id,v_contact_id,v_household_id,v_membership_id,p_request_type,
    p_target_household_member_id,
    nullif(trim(p_first_name),''),
    nullif(trim(p_last_name),''),
    p_relationship_type,p_sex,p_date_of_birth,
    nullif(lower(trim(p_email)),''),
    nullif(trim(p_notes),''),
    'submitted'
  )
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_health_metric_consents(p_provider_key text, p_allowed_metric_keys text[])
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_metric text;
  v_count integer:=0;
begin
  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.activated_at desc nulls last
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access not found';
  end if;

  if not exists (
    select 1 from public.health_integration_providers p
    where p.provider_key=p_provider_key and p.active=true
  ) then
    raise exception 'Health provider not found';
  end if;

  for v_metric in
    select jsonb_array_elements_text(p.supported_metrics)
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
  loop
    insert into public.health_metric_consents(
      user_id,contact_id,provider_key,metric_key,allowed,consented_at,revoked_at
    )
    values(
      (select auth.uid()),v_contact_id,p_provider_key,v_metric,
      v_metric=any(coalesce(p_allowed_metric_keys,array[]::text[])),
      case when v_metric=any(coalesce(p_allowed_metric_keys,array[]::text[])) then now() else null end,
      case when v_metric=any(coalesce(p_allowed_metric_keys,array[]::text[])) then null else now() end
    )
    on conflict(user_id,provider_key,metric_key)
    do update set
      allowed=excluded.allowed,
      consented_at=case when excluded.allowed then coalesce(health_metric_consents.consented_at,now()) else health_metric_consents.consented_at end,
      revoked_at=case when excluded.allowed then null else now() end,
      updated_at=now();
    v_count:=v_count+1;
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION private.queue_notification_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
declare
  v_prefs public.notification_preferences%rowtype;
  v_email text;
  v_phone text;
  v_sms_status text;
  v_wants_email boolean := false;
  v_wants_sms boolean := false;
  v_email_body text;
  v_sms_body text;
  v_scheduled_for timestamptz;
begin
  select * into v_prefs
  from public.notification_preferences
  where user_id=NEW.user_id;

  if v_prefs.user_id is null then
    insert into public.notification_preferences(user_id)
    values(NEW.user_id)
    on conflict (user_id) do nothing;

    select * into v_prefs
    from public.notification_preferences
    where user_id=NEW.user_id;
  end if;

  if NEW.notification_type='new_message' then
    v_wants_email:=coalesce(v_prefs.email_messages,false);
    v_wants_sms:=coalesce(v_prefs.sms_messages,false);

  elsif NEW.notification_type in (
    'appointment_reminder','appointment_scheduled','coaching_reminder',
    'coaching_session','assignment_available','assignment_completed',
    'companion_answer_ready'
  ) then
    v_wants_email:=coalesce(v_prefs.email_coaching_reminders,true);
    v_wants_sms:=coalesce(v_prefs.sms_coaching_reminders,false);

  elsif NEW.notification_type in (
    'program_update','account_active','course_assigned','course_available',
    'course_completed','resource_assigned','resource_available',
    'challenge_available','challenge_completed','goal_completed',
    'agreement_sent','agreement_viewed','agreement_signed','agreement_declined',
    'referral_engaged','referral_applicant','referral_converted',
    'referral_reward_approved','referral_reward_issued',
    'family_request_in_review','family_request_approved',
    'family_request_completed','family_request_declined'
  ) then
    v_wants_email:=coalesce(v_prefs.email_program_updates,true);
    v_wants_sms:=coalesce(v_prefs.sms_program_updates,false);

  elsif NEW.notification_type='billing_alert'
     or NEW.notification_type like 'billing_%' then
    v_wants_email:=coalesce(v_prefs.email_billing_alerts,true);
    v_wants_sms:=coalesce(v_prefs.sms_billing_alerts,false);

  else
    return NEW;
  end if;

  select u.email into v_email
  from auth.users u
  where u.id=NEW.user_id;

  if NEW.contact_id is not null then
    select c.phone,p.status
    into v_phone,v_sms_status
    from public.contacts c
    left join public.contact_sms_preferences p on p.contact_id=c.id
    where c.id=NEW.contact_id;
  end if;

  v_email_body:=coalesce(NEW.body,NEW.title);
  v_sms_body:=left(coalesce(NEW.body,NEW.title),1200);
  v_scheduled_for:=private.notification_scheduled_for(NEW.user_id);

  if v_wants_email then
    insert into public.notification_delivery_jobs(
      notification_id,user_id,contact_id,channel,provider,recipient,subject,body,
      status,block_reason,scheduled_for
    )
    values(
      NEW.id,NEW.user_id,NEW.contact_id,'email','resend',v_email,NEW.title,v_email_body,
      case when v_email is null then 'blocked' else 'queued' end,
      case when v_email is null then 'missing_email_address' else null end,
      v_scheduled_for
    )
    on conflict (notification_id,channel) do nothing;
  end if;

  if v_wants_sms then
    insert into public.notification_delivery_jobs(
      notification_id,user_id,contact_id,channel,provider,recipient,subject,body,
      status,block_reason,scheduled_for
    )
    values(
      NEW.id,NEW.user_id,NEW.contact_id,'sms','twilio',v_phone,null,v_sms_body,
      case
        when v_phone is null then 'blocked'
        when v_sms_status is distinct from 'opted_in' then 'blocked'
        else 'queued'
      end,
      case
        when v_phone is null then 'missing_phone_number'
        when v_sms_status is distinct from 'opted_in' then 'sms_consent_not_opted_in'
        else null
      end,
      v_scheduled_for
    )
    on conflict (notification_id,channel) do nothing;
  end if;

  return NEW;
end;
$function$

CREATE OR REPLACE FUNCTION private.apply_family_change_request(p_request_id uuid, p_actor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.family_change_requests%rowtype;
  v_contact_id uuid;
  v_target public.household_members%rowtype;
  v_existing_contact uuid;
begin
  select *
  into v_req
  from public.family_change_requests
  where id=p_request_id
  for update;

  if v_req.id is null then
    raise exception 'Family request was not found';
  end if;

  if not (
    private.staff_has_permission(p_actor_id,'crm.manage')
    and private.staff_can_access_contact(p_actor_id,v_req.contact_id)
  ) then
    raise exception 'Family request is not available';
  end if;

  if v_req.status='completed' then
    return;
  end if;

  if v_req.status not in ('approved','in_review','submitted') then
    raise exception 'Family request cannot be completed from its current status';
  end if;

  if v_req.household_id is null then
    raise exception 'Family request has no household';
  end if;

  if v_req.request_type='add_member' then
    if coalesce(trim(v_req.first_name),'')='' then
      raise exception 'First name is required';
    end if;

    if v_req.email is not null then
      select c.id
      into v_existing_contact
      from public.contacts c
      where lower(c.email)=lower(v_req.email)
      order by c.created_at
      limit 1;
    end if;

    if v_existing_contact is not null then
      if exists(
        select 1
        from public.household_members hm
        where hm.contact_id=v_existing_contact
          and hm.household_id<>v_req.household_id
          and hm.status='active'
      ) then
        raise exception 'That email is already attached to another active household';
      end if;

      v_contact_id:=v_existing_contact;

      update public.contacts
      set first_name=coalesce(nullif(trim(v_req.first_name),''),first_name),
          last_name=coalesce(nullif(trim(v_req.last_name),''),last_name),
          updated_at=now()
      where id=v_contact_id;
    else
      insert into public.contacts(
        first_name,last_name,email,lifecycle_stage,first_source,last_source,
        follow_up_status,consultation_status,record_kind
      )
      values(
        nullif(trim(v_req.first_name),''),
        nullif(trim(v_req.last_name),''),
        nullif(lower(trim(v_req.email)),''),
        'client',
        'family_hub',
        'family_hub',
        'closed',
        'not_scheduled',
        'crm'
      )
      returning id into v_contact_id;
    end if;

    insert into public.household_members(
      household_id,contact_id,relationship_type,sex,is_primary,date_of_birth,
      guardian_contact_id,status,updated_at
    )
    values(
      v_req.household_id,
      v_contact_id,
      v_req.relationship_type,
      v_req.sex,
      false,
      v_req.date_of_birth,
      case when v_req.relationship_type in ('child','dependent') then v_req.contact_id else null end,
      'active',
      now()
    )
    on conflict (household_id,contact_id) do update
    set relationship_type=excluded.relationship_type,
        sex=excluded.sex,
        date_of_birth=excluded.date_of_birth,
        guardian_contact_id=excluded.guardian_contact_id,
        status='active',
        updated_at=now();

  elsif v_req.request_type in ('update_member','remove_member') then
    select *
    into v_target
    from public.household_members hm
    where hm.id=v_req.target_household_member_id
      and hm.household_id=v_req.household_id
      and not hm.is_primary
    for update;

    if v_target.id is null then
      raise exception 'Family member is no longer available';
    end if;

    if v_req.request_type='remove_member' then
      update public.household_members
      set status='inactive',
          updated_at=now()
      where id=v_target.id;

    else
      update public.contacts
      set first_name=coalesce(nullif(trim(v_req.first_name),''),first_name),
          last_name=coalesce(nullif(trim(v_req.last_name),''),last_name),
          email=case
            when v_req.email is not null then nullif(lower(trim(v_req.email)),'')
            else email
          end,
          updated_at=now()
      where id=v_target.contact_id;

      update public.household_members
      set relationship_type=coalesce(v_req.relationship_type,relationship_type),
          sex=coalesce(v_req.sex,sex),
          date_of_birth=coalesce(v_req.date_of_birth,date_of_birth),
          guardian_contact_id=case
            when coalesce(v_req.relationship_type,relationship_type) in ('child','dependent')
              then v_req.contact_id
            else null
          end,
          updated_at=now()
      where id=v_target.id;
    end if;
  end if;

  perform private.refresh_household_type(v_req.household_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.review_family_change_request(p_request_id uuid, p_status text, p_staff_notes text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_current_status text;
begin
  if p_status not in ('in_review','approved','completed','declined') then
    raise exception 'Unsupported family request status';
  end if;

  select fcr.contact_id,fcr.status
  into v_contact_id,v_current_status
  from public.family_change_requests fcr
  where fcr.id=p_request_id;

  if v_contact_id is null
     or not (
       (select private.staff_has_permission((select auth.uid()),'crm.manage'))
       and private.staff_can_access_contact((select auth.uid()),v_contact_id)
     ) then
    raise exception 'Family request is not available';
  end if;

  if p_status='completed' and v_current_status<>'completed' then
    perform private.apply_family_change_request(p_request_id,(select auth.uid()));
  end if;

  update public.family_change_requests
  set status=p_status,
      staff_notes=case
        when p_staff_notes is not null then nullif(trim(p_staff_notes),'')
        else staff_notes
      end,
      reviewed_by=(select auth.uid()),
      reviewed_at=now(),
      updated_at=now()
  where id=p_request_id;

  return found;
end;
$function$

CREATE OR REPLACE FUNCTION private.submit_member_companion_question(p_user_id uuid, p_question_type text, p_question text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_mode text;
  v_effective_mode text;
  v_requires_coach boolean;
  v_coach_id uuid;
  v_request_id uuid;
  v_has_knowledge boolean;
  v_usage jsonb;
begin
  if coalesce(length(trim(p_question)),0)<2 or length(trim(p_question))>8000 then
    raise exception 'Question must be between 2 and 8000 characters';
  end if;

  select ca.contact_id,ca.membership_id
    into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=p_user_id
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null or v_membership_id is null then
    raise exception 'Active member access is required';
  end if;

  select qt.handling_mode,qt.requires_coach_assignment
    into v_mode,v_requires_coach
  from public.coach_companion_question_types qt
  where qt.question_type=p_question_type
    and qt.active
    and qt.member_visible
  limit 1;

  if v_mode is null then
    raise exception 'Choose a valid question category';
  end if;

  v_usage := private.consume_ai_advisor_entitlement(v_membership_id);

  select exists(
    select 1
    from public.coach_companion_knowledge_chunks ch
    join public.coach_companion_knowledge_sources s on s.id=ch.source_id
    where ch.active
      and ch.embedding is not null
      and s.status='approved'
  ) into v_has_knowledge;

  v_effective_mode:=case
    when v_mode='answer_if_supported' and not coalesce(v_has_knowledge,false)
      then 'coach_review'
    else v_mode
  end;

  if v_requires_coach or v_effective_mode<>'answer_if_supported' then
    select cca.coach_user_id
      into v_coach_id
    from public.client_coach_assignments cca
    where cca.contact_id=v_contact_id
      and cca.role='primary'
      and cca.status='active'
    limit 1;
  end if;

  insert into public.coach_companion_requests(
    contact_id,membership_id,requested_by_user_id,question_type,question,
    handling_mode,status,assigned_coach_id,metadata
  )
  values(
    v_contact_id,v_membership_id,p_user_id,p_question_type,trim(p_question),
    v_effective_mode,
    case when v_effective_mode='answer_if_supported' then 'queued' else 'coach_review' end,
    v_coach_id,
    jsonb_build_object(
      'source','member_app',
      'configured_handling_mode',v_mode,
      'knowledge_available',coalesce(v_has_knowledge,false),
      'usage',v_usage
    )
  )
  returning id into v_request_id;

  insert into public.coach_companion_usage_events(
    request_id,membership_id,contact_id,user_id,event_type,metadata
  )
  values(
    v_request_id,v_membership_id,v_contact_id,p_user_id,'question_submitted',
    jsonb_build_object('question_type',p_question_type,'usage',v_usage)
  );

  if v_effective_mode in ('coach_review','block_and_escalate') then
    perform private.create_companion_review(
      v_request_id,
      case
        when v_mode='answer_if_supported' and not coalesce(v_has_knowledge,false)
          then 'Approved Coach Companion knowledge is not yet available. Routed to human review.'
        when v_effective_mode='block_and_escalate'
          then 'Member question requires human review before any response.'
        else 'Member question routed to coach review.'
      end
    );

    insert into public.coach_companion_usage_events(
      request_id,membership_id,contact_id,user_id,event_type,metadata
    )
    values(
      v_request_id,v_membership_id,v_contact_id,p_user_id,
      case when v_effective_mode='block_and_escalate' then 'escalated' else 'coach_reviewed' end,
      jsonb_build_object('automatic_routing',true,'handling_mode',v_effective_mode)
    );
  end if;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.set_staff_phone_by_email_impl(p_email text, p_phone text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'private'
AS $function$
declare
  v_user_id uuid;
  v_email text;
  v_phone text;
begin
  if not private.staff_has_permission(auth.uid(),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  v_email := lower(trim(p_email));
  v_phone := nullif(trim(p_phone),'');

  if v_email is null or v_email='' then
    raise exception 'Email is required';
  end if;

  select u.id
    into v_user_id
  from auth.users u
  where lower(u.email)=v_email
  order by u.created_at
  limit 1;

  if v_user_id is not null then
    update public.staff_access
    set phone=v_phone,
        updated_at=now(),
        updated_by=auth.uid()
    where user_id=v_user_id;
  end if;

  update public.staff_invitations
  set metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('phone',v_phone),
      updated_at=now()
  where lower(email)=v_email
    and status in ('pending','invited','accepted');

  return v_user_id is not null;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_my_health_metric_consent(p_provider_key text, p_metric_key text, p_allowed boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
begin
  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.activated_at desc nulls last
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access not found';
  end if;

  if not exists (
    select 1
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
      and p.active=true
      and p.supported_metrics ? p_metric_key
  ) then
    raise exception 'Metric is not supported by this provider';
  end if;

  insert into public.health_metric_consents(
    user_id,contact_id,provider_key,metric_key,allowed,consented_at,revoked_at
  )
  values(
    (select auth.uid()),v_contact_id,p_provider_key,p_metric_key,p_allowed,
    case when p_allowed then now() else null end,
    case when p_allowed then null else now() end
  )
  on conflict(user_id,provider_key,metric_key)
  do update set
    allowed=excluded.allowed,
    consented_at=case when excluded.allowed then now() else health_metric_consents.consented_at end,
    revoked_at=case when excluded.allowed then null else now() end,
    updated_at=now();

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.capture_companion_source_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if tg_op='INSERT' then
    insert into public.coach_companion_source_revisions(
      source_id,source_key,title,source_type,version,status,content_text,
      approved_by,approved_at,metadata,revision_reason,changed_by
    )
    values(
      new.id,new.source_key,new.title,new.source_type,new.version,new.status,new.content_text,
      new.approved_by,new.approved_at,coalesce(new.metadata,'{}'::jsonb),
      'source_created',coalesce(new.created_by,auth.uid())
    );
    return new;
  end if;

  if row(
    old.source_key,old.title,old.source_type,old.version,old.status,old.content_text,
    old.approved_by,old.approved_at,old.metadata
  ) is distinct from row(
    new.source_key,new.title,new.source_type,new.version,new.status,new.content_text,
    new.approved_by,new.approved_at,new.metadata
  ) then
    insert into public.coach_companion_source_revisions(
      source_id,source_key,title,source_type,version,status,content_text,
      approved_by,approved_at,metadata,revision_reason,changed_by
    )
    values(
      new.id,new.source_key,new.title,new.source_type,new.version,new.status,new.content_text,
      new.approved_by,new.approved_at,coalesce(new.metadata,'{}'::jsonb),
      'source_updated',auth.uid()
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.log_companion_source_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_event text;
begin
  if tg_op='INSERT' then
    v_event := 'created';
  elsif old.content_checksum is distinct from new.content_checksum then
    v_event := 'content_changed';
  elsif old.status is distinct from new.status and new.status='approved' then
    v_event := 'approved';
  elsif old.status is distinct from new.status and new.status='retired' then
    v_event := 'retired';
  elsif old.status='approved' and new.status='draft' then
    v_event := 'approval_revoked';
  else
    return new;
  end if;

  insert into public.coach_companion_source_events(
    source_id,event_type,actor_user_id,detail
  )
  values(
    new.id,
    v_event,
    auth.uid(),
    jsonb_build_object(
      'status',new.status,
      'version',new.version,
      'ingestion_status',new.ingestion_status,
      'content_checksum',new.content_checksum
    )
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.retire_companion_source(p_source_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  update public.coach_companion_knowledge_sources
  set status='retired',
      updated_at=now()
  where id=p_source_id;

  if not found then
    raise exception 'Knowledge source not found';
  end if;

  update public.coach_companion_knowledge_chunks
  set active=false,
      updated_at=now()
  where source_id=p_source_id
    and active=true;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_companion_source_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_old_checksum text;
  v_new_checksum text;
begin
  v_new_checksum := md5(coalesce(new.content_text,''));
  v_old_checksum := case when tg_op='UPDATE' then md5(coalesce(old.content_text,'')) else null end;

  if tg_op='INSERT' then
    new.content_checksum := v_new_checksum;
    if coalesce(length(trim(new.content_text)),0)>0 then
      new.ingestion_status := 'queued';
    end if;
    return new;
  end if;

  if v_old_checksum is distinct from v_new_checksum then
    new.content_checksum := v_new_checksum;
    new.ingestion_status := case
      when coalesce(length(trim(new.content_text)),0)>0 then 'queued'
      else 'not_started'
    end;
    new.last_ingested_at := null;

    if old.status='approved' then
      new.status := 'draft';
      new.approved_by := null;
      new.approved_at := null;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_companion_source_ingestion(p_source_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_job_id uuid;
  v_source public.coach_companion_knowledge_sources%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  select * into v_source
  from public.coach_companion_knowledge_sources
  where id=p_source_id;

  if v_source.id is null then
    raise exception 'Knowledge source not found';
  end if;

  if coalesce(length(trim(v_source.content_text)),0)=0 then
    raise exception 'Knowledge source content is required before ingestion';
  end if;

  update public.coach_companion_knowledge_sources
  set ingestion_status='queued',
      updated_at=now()
  where id=p_source_id;

  insert into public.coach_companion_ingestion_jobs(
    source_id,job_type,status,requested_by
  )
  values(p_source_id,'full_ingest','queued',(select auth.uid()))
  returning id into v_job_id;

  insert into public.coach_companion_source_events(
    source_id,event_type,actor_user_id,detail
  )
  values(
    p_source_id,'ingestion_queued',(select auth.uid()),
    jsonb_build_object('job_id',v_job_id)
  );

  return v_job_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_companion_source(p_source_id uuid, p_version text DEFAULT NULL::text, p_review_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_source public.coach_companion_knowledge_sources%rowtype;
  v_chunk_count integer;
  v_embedded_count integer;
begin
  if not private.staff_has_permission((select auth.uid()),'companion.manage') then
    raise exception 'Coach Companion management permission is required';
  end if;

  select * into v_source
  from public.coach_companion_knowledge_sources
  where id=p_source_id;

  if v_source.id is null then
    raise exception 'Knowledge source not found';
  end if;

  if coalesce(length(trim(v_source.content_text)),0)=0 then
    raise exception 'Knowledge source content is required';
  end if;

  select
    count(*) filter(where ch.active)::integer,
    count(*) filter(where ch.active and ch.embedding is not null)::integer
  into v_chunk_count,v_embedded_count
  from public.coach_companion_knowledge_chunks ch
  where ch.source_id=p_source_id;

  if coalesce(v_chunk_count,0)=0 then
    raise exception 'Knowledge source has no active chunks';
  end if;

  if v_embedded_count<>v_chunk_count then
    raise exception 'All active knowledge chunks must have embeddings before approval';
  end if;

  update public.coach_companion_knowledge_sources
  set status='approved',
      version=coalesce(nullif(trim(p_version),''),version,'1.0'),
      ingestion_status='ready',
      approved_by=(select auth.uid()),
      approved_at=now(),
      review_due_at=p_review_due_at,
      updated_at=now()
  where id=p_source_id;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.emit_notification_sync_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_entity_id uuid;
begin
  if tg_op='DELETE' then
    v_contact_id:=old.contact_id;
    v_entity_id:=old.id;
  else
    v_contact_id:=new.contact_id;
    v_entity_id:=new.id;
  end if;

  if v_contact_id is null then
    return coalesce(new,old);
  end if;

  select hm.household_id
    into v_household_id
  from public.household_members hm
  where hm.contact_id=v_contact_id
    and hm.status='active'
  order by hm.is_primary desc,hm.created_at
  limit 1;

  insert into public.member_sync_events(
    contact_id,household_id,entity_type,entity_id,change_type,metadata
  )
  values(
    v_contact_id,
    v_household_id,
    'notification',
    v_entity_id,
    lower(tg_op),
    jsonb_build_object('table','member_notifications')
  );

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_my_companion_feedback(p_request_id uuid, p_helpful boolean, p_feedback_reason text DEFAULT NULL::text, p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_feedback_id uuid;
begin
  if p_feedback_reason is not null
     and p_feedback_reason not in (
       'not_relevant','unclear','incorrect','missing_context',
       'too_generic','needs_coach','other'
     ) then
    raise exception 'Invalid feedback reason';
  end if;

  if p_comment is not null and length(p_comment)>2000 then
    raise exception 'Feedback comment must be 2000 characters or fewer';
  end if;

  select r.contact_id into v_contact_id
  from public.coach_companion_requests r
  where r.id=p_request_id
    and r.requested_by_user_id=(select auth.uid())
    and r.status in ('answered','resolved');

  if v_contact_id is null then
    raise exception 'Answered Ask ReVitalized request not found';
  end if;

  insert into public.coach_companion_answer_feedback(
    request_id,contact_id,user_id,helpful,feedback_reason,comment
  )
  values(
    p_request_id,v_contact_id,(select auth.uid()),p_helpful,p_feedback_reason,nullif(trim(p_comment),'')
  )
  on conflict(request_id) do update
  set helpful=excluded.helpful,
      feedback_reason=excluded.feedback_reason,
      comment=excluded.comment,
      updated_at=now()
  returning id into v_feedback_id;

  return v_feedback_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.route_negative_companion_feedback()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_request public.coach_companion_requests%rowtype;
begin
  if new.helpful=true then
    return new;
  end if;

  select * into v_request
  from public.coach_companion_requests
  where id=new.request_id;

  if v_request.id is null then
    return new;
  end if;

  if v_request.answered_by_type='companion'
     or new.feedback_reason in ('incorrect','needs_coach','missing_context') then
    perform private.create_companion_review(
      new.request_id,
      'Member marked the Ask ReVitalized response as not helpful'
      || case
           when new.feedback_reason is not null
           then ' (' || new.feedback_reason || ').'
           else '.'
         end
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_my_mobile_health_batch(p_provider_key text, p_idempotency_key text, p_records jsonb, p_device_id uuid DEFAULT NULL::uuid, p_source_cursor text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_connection_id uuid;
  v_existing public.health_mobile_sync_batches%rowtype;
  v_batch_id uuid;
  v_sync_job_id uuid;
  v_received integer := 0;
  v_imported integer := 0;
  v_blocked integer := 0;
  v_duplicate integer := 0;
  v_record jsonb;
  v_metric_key text;
  v_external_record_id text;
  v_value_numeric numeric;
  v_value_boolean boolean;
  v_unit text;
  v_observed_at timestamptz;
  v_observed_end_at timestamptz;
  v_source_hash text;
  v_allowed boolean;
  v_supported boolean;
  v_inserted_id uuid;
  v_status text;
  v_record_error text;
begin
  if p_provider_key not in ('apple_health','health_connect') then
    raise exception 'Provider must be Apple Health or Android Health Connect';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  if jsonb_typeof(p_records) is distinct from 'array' then
    raise exception 'Health sync records must be a JSON array';
  end if;

  if jsonb_array_length(p_records)>1000 then
    raise exception 'Health sync batch cannot exceed 1000 records';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':health:' || p_idempotency_key,0
  ));

  select * into v_existing
  from public.health_mobile_sync_batches b
  where b.user_id=(select auth.uid())
    and b.idempotency_key=p_idempotency_key
  limit 1;

  if v_existing.id is not null then
    if v_existing.provider_key is distinct from p_provider_key then
      raise exception 'Idempotency key has already been used for another provider';
    end if;

    return jsonb_build_object(
      'batch_id',v_existing.id,
      'status',v_existing.status,
      'records_received',v_existing.records_received,
      'records_imported',v_existing.records_imported,
      'records_blocked',v_existing.records_blocked,
      'records_duplicate',v_existing.records_duplicate,
      'source_cursor',v_existing.source_cursor,
      'replayed',true
    );
  end if;

  select ca.contact_id,ca.membership_id
    into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if p_device_id is not null
     and not exists (
       select 1 from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  v_connection_id:=public.ensure_my_mobile_health_connection(
    p_provider_key,p_device_id
  );

  insert into public.health_mobile_sync_batches(
    user_id,contact_id,membership_id,device_id,connection_id,provider_key,
    idempotency_key,source_cursor,records_received,status,metadata
  )
  values(
    (select auth.uid()),v_contact_id,v_membership_id,p_device_id,v_connection_id,
    p_provider_key,p_idempotency_key,p_source_cursor,jsonb_array_length(p_records),
    'processing',
    jsonb_build_object('connection_mode','mobile_bridge')
  )
  returning id into v_batch_id;

  insert into public.health_sync_jobs(
    connection_id,contact_id,provider_key,job_type,status,scheduled_for,
    started_at,records_received,records_imported
  )
  values(
    v_connection_id,v_contact_id,p_provider_key,'incremental','processing',
    now(),now(),jsonb_array_length(p_records),0
  )
  returning id into v_sync_job_id;

  for v_record in
    select value from jsonb_array_elements(p_records)
  loop
    v_received:=v_received+1;
    v_record_error:=null;

    begin
      v_metric_key:=nullif(trim(v_record->>'metric_key'),'');
      v_external_record_id:=nullif(trim(v_record->>'external_record_id'),'');
      v_unit:=nullif(trim(v_record->>'unit'),'');
      v_value_numeric:=case
        when v_record ? 'value_numeric' and nullif(v_record->>'value_numeric','') is not null
          then (v_record->>'value_numeric')::numeric
        else null
      end;
      v_value_boolean:=case
        when v_record ? 'value_boolean' and nullif(v_record->>'value_boolean','') is not null
          then (v_record->>'value_boolean')::boolean
        else null
      end;
      v_observed_at:=case
        when nullif(v_record->>'observed_at','') is not null
          then (v_record->>'observed_at')::timestamptz
        else null
      end;
      v_observed_end_at:=case
        when nullif(v_record->>'observed_end_at','') is not null
          then (v_record->>'observed_end_at')::timestamptz
        else null
      end;
    exception
      when others then
        v_record_error:=left(sqlerrm,500);
    end;

    if v_record_error is not null
       or v_metric_key is null
       or v_observed_at is null
       or ((v_value_numeric is null and v_value_boolean is null)
           or (v_value_numeric is not null and v_value_boolean is not null)) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    select p.supported_metrics ? v_metric_key
      into v_supported
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
      and p.active
      and p.connection_mode='mobile_bridge';

    if not coalesce(v_supported,false) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    select coalesce(c.allowed,false)
      into v_allowed
    from public.health_metric_consents c
    where c.user_id=(select auth.uid())
      and c.contact_id=v_contact_id
      and c.provider_key=p_provider_key
      and c.metric_key=v_metric_key
    order by c.updated_at desc
    limit 1;

    if not coalesce(v_allowed,false) then
      v_blocked:=v_blocked+1;
      continue;
    end if;

    v_source_hash:=md5(
      concat_ws('|',
        p_provider_key,
        v_metric_key,
        coalesce(v_external_record_id,''),
        v_observed_at::text,
        coalesce(v_observed_end_at::text,''),
        coalesce(v_value_numeric::text,''),
        coalesce(v_value_boolean::text,''),
        coalesce(v_unit,'')
      )
    );

    v_inserted_id:=null;

    insert into public.health_observations(
      contact_id,membership_id,connection_id,provider_key,metric_key,
      value_numeric,value_boolean,unit,observed_at,observed_end_at,
      external_record_id,source_payload_hash,imported_at,metadata
    )
    values(
      v_contact_id,v_membership_id,v_connection_id,p_provider_key,v_metric_key,
      v_value_numeric,v_value_boolean,v_unit,v_observed_at,v_observed_end_at,
      v_external_record_id,v_source_hash,now(),
      coalesce(v_record->'metadata','{}'::jsonb)
        || jsonb_build_object(
          'mobile_batch_id',v_batch_id,
          'device_id',p_device_id
        )
    )
    on conflict do nothing
    returning id into v_inserted_id;

    if v_inserted_id is null then
      v_duplicate:=v_duplicate+1;
    else
      v_imported:=v_imported+1;
    end if;
  end loop;

  v_status:=case
    when v_blocked>0 then 'partial'
    else 'completed'
  end;

  update public.health_mobile_sync_batches
  set records_received=v_received,
      records_imported=v_imported,
      records_blocked=v_blocked,
      records_duplicate=v_duplicate,
      status=v_status,
      completed_at=now()
  where id=v_batch_id;

  update public.health_integration_connections
  set status='connected',
      last_sync_at=now(),
      last_successful_sync_at=case
        when v_imported>0 or v_duplicate>0 then now()
        else last_successful_sync_at
      end,
      last_error=case
        when v_blocked>0 then v_blocked::text || ' record(s) blocked during last sync'
        else null
      end,
      sync_cursor=coalesce(p_source_cursor,sync_cursor),
      metadata=coalesce(metadata,'{}'::jsonb)
        || jsonb_build_object(
          'last_device_id',p_device_id,
          'last_mobile_batch_id',v_batch_id
        ),
      updated_at=now()
  where id=v_connection_id;

  update public.health_sync_jobs
  set status='completed',
      completed_at=now(),
      records_received=v_received,
      records_imported=v_imported,
      error_message=case
        when v_blocked>0 then v_blocked::text || ' record(s) blocked'
        else null
      end,
      updated_at=now()
  where id=v_sync_job_id;

  perform private.touch_member_device(p_device_id);

  return jsonb_build_object(
    'batch_id',v_batch_id,
    'status',v_status,
    'records_received',v_received,
    'records_imported',v_imported,
    'records_blocked',v_blocked,
    'records_duplicate',v_duplicate,
    'source_cursor',p_source_cursor,
    'replayed',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_app_runtime_config(p_config_key text, p_config_value jsonb, p_description text DEFAULT NULL::text, p_member_visible boolean DEFAULT true, p_active boolean DEFAULT true)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  update public.app_runtime_config
  set config_value=p_config_value,
      description=coalesce(p_description,description),
      member_visible=p_member_visible,
      active=p_active,
      updated_by=(select auth.uid()),
      updated_at=now()
  where config_key=p_config_key;

  if not found then
    raise exception 'Runtime config key not found';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.existing_mutation_response(p_idempotency_key text, p_mutation_type text, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_row public.member_mutation_receipts%rowtype;
begin
  select * into v_row
  from public.member_mutation_receipts
  where user_id=(select auth.uid())
    and idempotency_key=p_idempotency_key
  limit 1;

  if v_row.id is null then
    return null;
  end if;

  if v_row.mutation_type is distinct from p_mutation_type
     or v_row.request_hash is distinct from p_request_hash then
    raise exception 'Idempotency key has already been used for a different request';
  end if;

  return v_row.response_payload;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_my_habit_checkin(p_idempotency_key text, p_habit_id uuid, p_checkin_date date, p_value numeric, p_note text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_id uuid;
  v_response jsonb;
begin
  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_habit_id::text,p_checkin_date::text,p_value::text,coalesce(p_note,'')));
  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'habit_checkin',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
    and exists (
      select 1 from public.client_habits h
      where h.id=p_habit_id
        and h.contact_id=ca.contact_id
    )
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Habit is not available to the current member';
  end if;

  insert into public.habit_checkins(
    habit_id,contact_id,checkin_date,value,note,source,created_by
  )
  values(
    p_habit_id,v_contact_id,p_checkin_date,p_value,
    nullif(trim(p_note),''),'member',(select auth.uid())
  )
  on conflict(habit_id,contact_id,checkin_date) do update
  set value=excluded.value,
      note=excluded.note,
      source='member',
      created_by=(select auth.uid())
  returning id into v_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','habit_checkin',
    'record_id',v_id,
    'contact_id',v_contact_id,
    'checkin_date',p_checkin_date
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'habit_checkin',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_my_progress_entry(p_idempotency_key text, p_metric_key text, p_value_numeric numeric DEFAULT NULL::numeric, p_value_boolean boolean DEFAULT NULL::boolean, p_recorded_at timestamp with time zone DEFAULT now(), p_note text DEFAULT NULL::text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_hash text;
  v_existing jsonb;
  v_id uuid;
  v_response jsonb;
begin
  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  if (p_value_numeric is null and p_value_boolean is null)
     or (p_value_numeric is not null and p_value_boolean is not null) then
    raise exception 'Provide exactly one progress value';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_metric_key,coalesce(p_value_numeric::text,''),
    coalesce(p_value_boolean::text,''),p_recorded_at::text,coalesce(p_note,'')));

  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'progress_entry',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select ca.contact_id,ca.membership_id
  into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if not exists (
    select 1 from public.progress_metric_catalog pmc
    where pmc.metric_key=p_metric_key
      and pmc.active
      and pmc.member_trackable
  ) then
    raise exception 'Metric is not available for member tracking';
  end if;

  insert into public.progress_entries(
    contact_id,membership_id,metric_key,value_numeric,value_boolean,
    recorded_at,source,created_by,note,metadata
  )
  values(
    v_contact_id,v_membership_id,p_metric_key,p_value_numeric,p_value_boolean,
    coalesce(p_recorded_at,now()),'member',(select auth.uid()),
    nullif(trim(p_note),''),
    jsonb_build_object(
      'idempotency_key',p_idempotency_key,
      'device_id',p_device_id
    )
  )
  returning id into v_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','progress_entry',
    'record_id',v_id,
    'contact_id',v_contact_id,
    'metric_key',p_metric_key,
    'recorded_at',coalesce(p_recorded_at,now())
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_idempotency_key,
    'progress_entry',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_my_workout_status(p_idempotency_key text, p_assignment_id uuid, p_status text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_response jsonb;
begin
  if p_status not in ('assigned','completed','skipped') then
    raise exception 'Invalid workout status';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
