$function$

CREATE OR REPLACE FUNCTION public.sync_my_meal_status(p_idempotency_key text, p_meal_item_id uuid, p_status text, p_adherence_percent numeric DEFAULT NULL::numeric, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_hash text;
  v_existing jsonb;
  v_response jsonb;
begin
  if p_status not in ('planned','completed','skipped','substituted') then
    raise exception 'Invalid meal status';
  end if;

  if p_adherence_percent is not null
     and (p_adherence_percent<0 or p_adherence_percent>100) then
    raise exception 'Adherence percent must be between 0 and 100';
  end if;

  if coalesce(length(trim(p_idempotency_key)),0)<8 then
    raise exception 'A valid idempotency key is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    (select auth.uid())::text || ':' || p_idempotency_key,0
  ));

  v_hash:=md5(concat_ws('|',p_meal_item_id::text,p_status,coalesce(p_adherence_percent::text,'')));
  v_existing:=private.existing_mutation_response(
    p_idempotency_key,'meal_status',v_hash
  );
  if v_existing is not null then
    return v_existing;
  end if;

  select mi.contact_id into v_contact_id
  from public.client_meal_plan_items mi
  join public.client_access ca on ca.contact_id=mi.contact_id
  where mi.id=p_meal_item_id
    and ca.user_id=(select auth.uid())
    and ca.status='active'
  limit 1;

  if v_contact_id is null then
    raise exception 'Meal item is not available to the current member';
  end if;

  update public.client_meal_plan_items
  set status=p_status,
      adherence_percent=p_adherence_percent,
      completed_at=case when p_status='completed' then coalesce(completed_at,now()) else null end
  where id=p_meal_item_id;

  v_response:=jsonb_build_object(
    'status','ok',
    'mutation_type','meal_status',
    'record_id',p_meal_item_id,
    'contact_id',v_contact_id,
    'meal_status',p_status,
    'adherence_percent',p_adherence_percent
  );

  insert into public.member_mutation_receipts(
    user_id,contact_id,device_id,idempotency_key,mutation_type,request_hash,response_payload
  )
  values(
