    'meal_status',v_hash,v_response
  );

  perform private.touch_member_device(p_device_id);
  return v_response;
end;
$function$

CREATE OR REPLACE FUNCTION private.emit_member_sync_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_household_id uuid;
  v_entity_id uuid;
  v_change text;
begin
  v_change:=lower(tg_op);

  if tg_op='DELETE' then
    v_contact_id:=old.contact_id;
    v_entity_id:=old.id;
  else
    v_contact_id:=new.contact_id;
    v_entity_id:=new.id;
  end if;

  if v_contact_id is null then
    return coalesce(new,old);
  end if;

  select hm.household_id
    into v_household_id
  from public.household_members hm
  where hm.contact_id=v_contact_id
    and hm.status='active'
  order by hm.is_primary desc,hm.created_at
  limit 1;

  insert into public.member_sync_events(
    contact_id,household_id,entity_type,entity_id,change_type,metadata
  )
  values(
    v_contact_id,
    v_household_id,
    tg_argv[0],
    v_entity_id,
    v_change,
    jsonb_build_object('table',tg_table_name)
  );

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION public.track_my_app_event(p_event_key text, p_session_id uuid DEFAULT NULL::uuid, p_device_id uuid DEFAULT NULL::uuid, p_route_key text DEFAULT NULL::text, p_feature_key text DEFAULT NULL::text, p_properties jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_event_id bigint;
begin
  if coalesce(length(trim(p_event_key)),0)<2 or length(trim(p_event_key))>100 then
    raise exception 'A valid event key is required';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if p_session_id is not null
     and not exists (
       select 1 from public.member_app_sessions s
       where s.id=p_session_id
         and s.user_id=(select auth.uid())
     ) then
    raise exception 'Session is not available to the current member';
  end if;

  if p_device_id is not null
     and not exists (
       select 1 from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  if p_route_key is not null
     and not exists (
       select 1 from public.app_route_registry r
       where r.route_key=p_route_key
         and r.active
     ) then
    raise exception 'Unknown app route';
  end if;

  insert into public.member_app_events(
    user_id,contact_id,device_id,session_id,event_key,route_key,
    feature_key,properties
  )
  values(
    (select auth.uid()),v_contact_id,p_device_id,p_session_id,
    trim(p_event_key),p_route_key,p_feature_key,coalesce(p_properties,'{}'::jsonb)
  )
  returning id into v_event_id;

  if p_session_id is not null then
    update public.member_app_sessions
    set last_seen_at=now()
    where id=p_session_id
      and user_id=(select auth.uid());
  end if;

  perform private.touch_member_device(p_device_id);
  return v_event_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_my_mobile_health_connection(p_provider_key text, p_device_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_contact_id uuid;
  v_membership_id uuid;
  v_connection_id uuid;
begin
  if p_provider_key not in ('apple_health','health_connect') then
    raise exception 'Provider must be Apple Health or Android Health Connect';
  end if;

  if not exists (
    select 1
    from public.health_integration_providers p
    where p.provider_key=p_provider_key
      and p.active
      and p.connection_mode='mobile_bridge'
  ) then
    raise exception 'Mobile health provider is not currently available';
  end if;

  select ca.contact_id,ca.membership_id
    into v_contact_id,v_membership_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  if p_device_id is not null
     and not exists (
       select 1
       from public.member_devices d
       where d.id=p_device_id
         and d.user_id=(select auth.uid())
         and d.revoked_at is null
     ) then
    raise exception 'Device is not available to the current member';
  end if;

  insert into public.health_integration_connections(
    contact_id,membership_id,user_id,provider_key,status,
    connected_at,metadata
  )
  values(
    v_contact_id,v_membership_id,(select auth.uid()),p_provider_key,
    'connected',now(),
    jsonb_build_object(
      'connection_mode','mobile_bridge',
      'device_id',p_device_id
    )
  )
  on conflict(contact_id,provider_key) do update
  set membership_id=excluded.membership_id,
      user_id=(select auth.uid()),
      status=case
        when public.health_integration_connections.status in ('revoked','disconnected')
          then 'connected'
        else public.health_integration_connections.status
      end,
      connected_at=coalesce(public.health_integration_connections.connected_at,now()),
      metadata=coalesce(public.health_integration_connections.metadata,'{}'::jsonb)
        || jsonb_build_object('device_id',p_device_id,'connection_mode','mobile_bridge'),
      updated_at=now()
  returning id into v_connection_id;

  perform private.touch_member_device(p_device_id);
  return v_connection_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.prepare_privacy_export(p_request_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
  v_export_id uuid;
  v_manifest jsonb;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null then
    raise exception 'Privacy request not found';
  end if;

  if v_req.request_type<>'data_export' then
    raise exception 'Privacy request is not a data export request';
  end if;

  if v_req.status not in ('submitted','in_review','approved','processing') then
    raise exception 'Privacy request is not eligible for export preparation';
  end if;

  v_manifest:=jsonb_build_object(
    'contact_id',v_req.contact_id,
    'requested_at',v_req.requested_at,
    'scope',v_req.scope,
    'sections',jsonb_build_array(
      'profile',
      'membership',
      'coaching',
      'goals_habits_progress',
      'health_connections_consents_observations',
      'courses',
      'notifications',
      'devices',
      'privacy_requests'
    )
  );

  insert into public.member_privacy_exports(
    privacy_request_id,user_id,contact_id,status,export_scope,manifest,created_by
  )
  values(
    v_req.id,v_req.user_id,v_req.contact_id,'queued',v_req.scope,v_manifest,(select auth.uid())
  )
  on conflict(privacy_request_id) do update
  set status=case
        when public.member_privacy_exports.status in ('ready','processing') then public.member_privacy_exports.status
        else 'queued'
      end,
      export_scope=excluded.export_scope,
      manifest=excluded.manifest,
      error_message=null,
      updated_at=now()
  returning id into v_export_id;

  update public.member_privacy_requests
  set status='processing',
      assigned_to=coalesce(assigned_to,(select auth.uid())),
      reviewed_at=coalesce(reviewed_at,now()),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'export_queued',(select auth.uid()),
    jsonb_build_object('export_id',v_export_id)
  );

  return v_export_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_my_privacy_request(p_request_type text, p_scope jsonb DEFAULT '{}'::jsonb, p_member_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_contact_id uuid;
  v_request_id uuid;
begin
  if p_request_type not in (
    'data_export','health_data_delete','account_delete','correction','other'
  ) then
    raise exception 'Invalid privacy request type';
  end if;

  if p_member_note is not null and length(p_member_note)>4000 then
    raise exception 'Privacy request note must be 4000 characters or fewer';
  end if;

  select ca.contact_id into v_contact_id
  from public.client_access ca
  where ca.user_id=(select auth.uid())
    and ca.status='active'
  order by ca.updated_at desc
  limit 1;

  if v_contact_id is null then
    raise exception 'Active member access is required';
  end if;

  insert into public.member_privacy_requests(
    user_id,contact_id,request_type,scope,status,member_note
  )
  values(
    (select auth.uid()),v_contact_id,p_request_type,coalesce(p_scope,'{}'::jsonb),
    'submitted',nullif(trim(p_member_note),'')
  )
  returning id into v_request_id;

  return v_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_privacy_export(p_export_id uuid, p_storage_path text, p_file_size_bytes bigint, p_checksum text, p_manifest jsonb DEFAULT NULL::jsonb, p_expires_at timestamp with time zone DEFAULT (now() + '7 days'::interval))
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_export public.member_privacy_exports%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_export
  from public.member_privacy_exports
  where id=p_export_id
  for update;

  if v_export.id is null then
    raise exception 'Privacy export not found';
  end if;

  if coalesce(length(trim(p_storage_path)),0)<3 then
    raise exception 'A valid storage path is required';
  end if;

  update public.member_privacy_exports
  set status='ready',
      storage_path=trim(p_storage_path),
      file_size_bytes=p_file_size_bytes,
      checksum=nullif(trim(p_checksum),''),
      manifest=coalesce(p_manifest,manifest),
      expires_at=p_expires_at,
      ready_at=now(),
      error_message=null,
      updated_at=now()
  where id=p_export_id;

  update public.member_privacy_requests
  set status='completed',
      completed_at=now(),
      updated_at=now()
  where id=v_export.privacy_request_id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_export.privacy_request_id,'export_ready',(select auth.uid()),
    jsonb_build_object(
      'export_id',p_export_id,
      'storage_path',trim(p_storage_path),
      'expires_at',p_expires_at
    )
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_health_data_delete_request(p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null or v_req.request_type<>'health_data_delete' then
    raise exception 'Health-data deletion request not found';
  end if;

  update public.member_privacy_requests
  set status='approved',
      assigned_to=coalesce(assigned_to,(select auth.uid())),
      reviewed_at=coalesce(reviewed_at,now()),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'health_delete_approved',(select auth.uid()),
    jsonb_build_object('scope',v_req.scope)
  );

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.execute_health_data_delete_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_req public.member_privacy_requests%rowtype;
  v_provider text;
  v_deleted_observations integer := 0;
  v_deleted_batches integer := 0;
begin
  if not private.staff_has_permission((select auth.uid()),'staff.manage') then
    raise exception 'Staff management permission is required';
  end if;

  select * into v_req
  from public.member_privacy_requests
  where id=p_request_id
  for update;

  if v_req.id is null or v_req.request_type<>'health_data_delete' then
    raise exception 'Health-data deletion request not found';
  end if;

  if v_req.status<>'approved' then
    raise exception 'Health-data deletion request must be approved first';
  end if;

  v_provider:=nullif(v_req.scope->>'provider_key','');

  update public.health_integration_connections
  set status='disconnected',
      credential_reference=null,
      granted_scopes='{}'::jsonb,
      last_error=null,
      updated_at=now()
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);

  update public.health_metric_consents
  set allowed=false,
      revoked_at=now(),
      updated_at=now()
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);

  delete from public.health_observations
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);
  get diagnostics v_deleted_observations=row_count;

  delete from public.health_mobile_sync_batches
  where contact_id=v_req.contact_id
    and (v_provider is null or provider_key=v_provider);
  get diagnostics v_deleted_batches=row_count;

  update public.member_privacy_requests
  set status='completed',
      completed_at=now(),
      updated_at=now()
  where id=v_req.id;

  insert into public.member_privacy_actions(
    privacy_request_id,action_type,actor_user_id,detail
  )
  values(
    v_req.id,'health_delete_executed',(select auth.uid()),
    jsonb_build_object(
      'provider_key',v_provider,
      'deleted_health_observations',v_deleted_observations,
      'deleted_mobile_sync_batches',v_deleted_batches
    )
  );

  return jsonb_build_object(
    'status','completed',
    'provider_key',v_provider,
    'deleted_health_observations',v_deleted_observations,
    'deleted_mobile_sync_batches',v_deleted_batches
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_payment_record_to_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_paid_total bigint;
  v_refund_total bigint;
  v_net_total bigint;
  v_activation public.journey_enrollment_activations%rowtype;
begin
  if coalesce(new.activation_id,old.activation_id) is null then
    return coalesce(new,old);
  end if;

  select * into v_activation
  from public.journey_enrollment_activations
  where id=coalesce(new.activation_id,old.activation_id);

  if v_activation.id is null then
    return coalesce(new,old);
  end if;

  select
    coalesce(sum(amount_cents) filter(
      where transaction_type in ('payment','adjustment')
        and status='recorded'
    ),0),
    coalesce(sum(amount_cents) filter(
      where transaction_type in ('refund','reversal')
        and status='recorded'
    ),0)
  into v_paid_total,v_refund_total
  from public.payment_records
  where activation_id=v_activation.id;

  v_net_total:=v_paid_total-v_refund_total;

  update public.journey_enrollment_activations
  set payment_status=case
        when v_activation.payment_status='waived' then 'waived'
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents then 'paid'
        when v_net_total>0 then 'authorized'
        when v_refund_total>0 and v_net_total<=0 then 'refunded'
        else 'pending'
      end,
      paid_at=case
        when v_activation.payment_status='waived' then paid_at
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents
          then coalesce(paid_at,now())
        else null
      end,
      payment_completion_method=case
        when v_activation.payment_status='waived' then payment_completion_method
        when v_activation.amount_cents is not null and v_net_total>=v_activation.amount_cents
          then coalesce(payment_completion_method,'payment_records_reconciled')
        else payment_completion_method
      end,
      payment_reference=case
        when tg_op<>'DELETE' and new.reference_number is not null then new.reference_number
        else payment_reference
      end,
      updated_at=now()
  where id=v_activation.id;

  return coalesce(new,old);
end;
$function$

CREATE OR REPLACE FUNCTION private.sync_staff_onboarding_from_agreements()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
declare
  v_staff_user_id uuid;
  v_required integer;
  v_incomplete integer;
  v_declined integer;
begin
  v_staff_user_id:=case
    when tg_table_name='staff_agreements' then coalesce(new.staff_user_id,old.staff_user_id)
    else (
      select sa.staff_user_id
      from public.staff_agreements sa
      where sa.id=coalesce(new.staff_agreement_id,old.staff_agreement_id)
    )
  end;

  if v_staff_user_id is null then
    return coalesce(new,old);
  end if;

  select
    count(*) filter(where sa.required)::integer,
    count(*) filter(where sa.required and sa.status not in ('signed','waived'))::integer,
    count(*) filter(where sa.required and sa.status='declined')::integer
  into v_required,v_incomplete,v_declined
  from public.staff_agreements sa
  where sa.staff_user_id=v_staff_user_id;

  update public.staff_access
  set onboarding_status=case
        when status<>'active' then onboarding_status
        when coalesce(v_declined,0)>0 then 'blocked'
        when coalesce(v_required,0)=0 then 'complete'
        when coalesce(v_incomplete,0)=0 then 'complete'
        else 'pending'
      end,
      updated_at=now()
  where user_id=v_staff_user_id;

  return coalesce(new,old);
end;
$function$
